/// Immutable resolver used only while validating/materializing one already
/// validated V50 package. Source identity digests come exclusively from the
/// non-C13 generic journal; inventory atoms come from canonical non-C13 record
/// sections produced by the shipping backup encoder.
private struct EntityIdentityResolutionPackageResolverV1:
    EntityIdentityResolutionCanonicalSourceResolvingV1 {
    private struct JournalImage {
        let identity: WorkspaceEntityIdentityV1
        let revision: UInt64
        let semanticSHA256: String
    }

    let workspaceID: WorkspaceID
    let snapshots: [EntityIdentitySnapshotV1]
    let aliasLinks: [EntityAliasLinkV1]
    let atomsByFamily:
        [EntityConsolidationInventoryFamilyV1: [EntityConsolidationInventoryAtomV1]]

    init(records: V4BackupRecordsV1, snapshot: EntityIdentityResolutionBackupSnapshotV1) throws {
        try snapshot.validate()
        guard let history = records.mutationHistory else {
            throw BackupRestoreServiceError.invalidPackage
        }
        let required = snapshot.aliasLinks.flatMap { [$0.alias, $0.canonicalEntity] }
            + snapshot.consolidationReceipts.flatMap { [$0.source, $0.survivor] }
        let uniqueRequired = Dictionary(grouping: required, by: { $0.identity }).values
        guard uniqueRequired.allSatisfy({ Set($0).count == 1 }) else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }

        var journalImages: [JournalImage] = []
        for record in history.receipts {
            let envelope = try MutationEnvelopeV1.decodeCanonical(from: record.envelopeData)
            if case .applyEntityIdentityResolution = envelope.command { continue }
            let receipt = try MutationReceiptV1.decodeCanonical(from: record.receiptData)
            for image in receipt.postImages {
                let identity = try image.identity
                guard identity.kind != .entityAliasLink,
                      identity.kind != .entityConsolidationReceipt else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                journalImages.append(.init(
                    identity: identity,
                    revision: image.revision,
                    semanticSHA256: image.semanticSHA256
                ))
            }
        }

        let resolved = try uniqueRequired.map { group -> EntityIdentitySnapshotV1 in
            guard let expected = group.first else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            let terminals = history.entityRevisions.filter { $0.identity == expected.identity }
            guard terminals.count == 1, let terminal = terminals.first,
                  terminal.revision == expected.revision else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            let identityImages = journalImages.filter { $0.identity == expected.identity }
            guard identityImages.allSatisfy({ $0.revision <= terminal.revision }) else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            let exact = identityImages.filter { $0.revision == terminal.revision }
            let digest: String
            if exact.count == 1, let image = exact.first {
                digest = image.semanticSHA256
            } else if exact.isEmpty,
                      let external = terminal.externalProjectionSHA256,
                      MutationEnvelopeV1.isSHA256(external) {
                digest = external
            } else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            let value = try EntityIdentitySnapshotV1(
                workspaceID: snapshot.workspaceID,
                identity: terminal.identity,
                revision: terminal.revision,
                entitySHA256: digest
            )
            guard value == expected else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            return value
        }.sorted { $0.stableKey < $1.stableKey }

        let atoms = try BackupCanonicalEncoderV1()
            .entityIdentityResolutionInventoryAtoms(records)
        guard Set(atoms.keys) == Set(EntityConsolidationInventoryFamilyV1.allCases) else {
            throw BackupRestoreServiceError.invalidPackage
        }
        workspaceID = snapshot.workspaceID
        snapshots = resolved
        aliasLinks = snapshot.aliasLinks
        atomsByFamily = atoms
    }

    func resolveEntityIdentity(
        _ identity: WorkspaceEntityIdentityV1,
        workspaceID: WorkspaceID,
        revision: UInt64
    ) throws -> EntityIdentitySnapshotV1 {
        guard workspaceID == self.workspaceID else {
            throw EntityIdentityResolutionFailureV1.wrongWorkspace
        }
        let matches = snapshots.filter { $0.identity == identity && $0.revision == revision }
        guard matches.count == 1, let value = matches.first else {
            throw EntityIdentityResolutionFailureV1.staleRevision
        }
        return value
    }

    func aliasPath(
        from alias: WorkspaceEntityIdentityV1,
        workspaceID: WorkspaceID
    ) throws -> [WorkspaceEntityIdentityV1] {
        guard workspaceID == self.workspaceID else {
            throw EntityIdentityResolutionFailureV1.wrongWorkspace
        }
        var current = alias
        var result: [WorkspaceEntityIdentityV1] = []
        var visited = Set([alias])
        while true {
            let candidates = aliasLinks.filter { $0.alias.identity == current }
            guard !candidates.isEmpty else { return result }
            let maximumRevision = candidates.map(\.revision).max()
            let latest = candidates.filter { $0.revision == maximumRevision }
            guard latest.count == 1, let link = latest.first,
                  visited.insert(link.canonicalEntity.identity).inserted,
                  result.count < EntityIdentityResolutionLimitsV1.maximumQueryResults else {
                throw EntityIdentityResolutionFailureV1.aliasCycle
            }
            result.append(link.canonicalEntity.identity)
            current = link.canonicalEntity.identity
        }
    }

    func canonicalConsolidationAtoms(
        source: EntityIdentitySnapshotV1,
        survivor: EntityIdentitySnapshotV1,
        family: EntityConsolidationInventoryFamilyV1
    ) throws -> [EntityConsolidationInventoryAtomV1] {
        guard source.workspaceID == workspaceID, survivor.workspaceID == workspaceID,
              source.identity != survivor.identity,
              try resolveEntityIdentity(source.identity, workspaceID: workspaceID, revision: source.revision) == source,
              try resolveEntityIdentity(survivor.identity, workspaceID: workspaceID, revision: survivor.revision) == survivor,
              let atoms = atomsByFamily[family] else {
            throw EntityIdentityResolutionFailureV1.incompleteInventory
        }
        return atoms
    }

    func resolve(
        workspaceID: WorkspaceID,
        entityID: WorkspaceEntityIdentityV1,
        expectedRevision: UInt64
    ) throws -> EntityIdentityResolutionCanonicalSourceV1 {
        let snapshot = try resolveEntityIdentity(
            entityID, workspaceID: workspaceID, revision: expectedRevision
        )
        guard let counterpart = snapshots.first(where: { $0.identity != snapshot.identity }) else {
            throw EntityIdentityResolutionFailureV1.incompleteInventory
        }
        return try EntityIdentityResolutionCanonicalSourceV1(
            snapshot: snapshot,
            inventory: try canonicalConsolidationInventory(
                source: snapshot, survivor: counterpart
            )
        )
    }
}

/// Bounded retained-generation sources. The restore service mints these only
/// for composition-selected current children after the media owner's read-only
/// snapshot. Original named ancestors and file facts are checked on every copy.
struct CheckRunnerPhotoRestoreRetainedMembersV1: Sendable {
    private let members: ValidatedV4BackupMembersV1
    private let files: [String: CheckRunnerPhotoMediaBackupFileV1]
    private let observations: [String: StreamingArchiveSourceObservationV1]
    private let metadata: [String: Data]
    private let rootIdentity: StreamingArchiveRootIdentityV1

    fileprivate init(rootURL: URL, rootIdentity: StreamingArchiveRootIdentityV1,
        snapshots: [CheckRunnerPhotoMediaBackupChildSnapshotV1],
        plan: CheckRunnerPhotoBackupRestorePlanV1) throws {
        let failure = BackupRestoreServiceError.invalidPackage
        let wanted = Set(plan.children.map(\.childDraftID))
        guard Set(snapshots.map(\.childDraftID)).count == snapshots.count,
              Set(snapshots.map(\.childDraftID)) == wanted,
              let device = dev_t(exactly: rootIdentity.device),
              let inode = ino_t(exactly: rootIdentity.inode) else { throw failure }
        var files: [String: CheckRunnerPhotoMediaBackupFileV1] = [:]
        var descriptors: [String: ValidatedV4BackupMembersV1.Descriptor] = [:]
        var observations: [String: StreamingArchiveSourceObservationV1] = [:]
        let observer = StreamingArchiveService()
        for snapshot in snapshots {
            for file in snapshot.files {
                if let existing = files[file.entry.path], existing != file { throw failure }
                let descriptor = ValidatedV4BackupMembersV1.Descriptor(
                    byteCount: Int64(file.entry.byteCount), sha256: file.entry.sha256)
                if let existing = descriptors[file.generationRelativePath], existing != descriptor { throw failure }
                let writeEntry = StreamingArchiveWriteEntryV1(path: file.entry.path,
                    mimeType: file.entry.mimeType, sourceRootURL: rootURL,
                    sourceRelativePath: file.generationRelativePath,
                    expectedSourceRootIdentity: rootIdentity,
                    expectedUncompressedByteCount: Int64(file.entry.byteCount),
                    expectedContentSHA256: file.entry.sha256, compression: .stored)
                let observation = try observer.sourceObservation(writeEntry)
                guard observation.file == file.snapshot else { throw failure }
                files[file.entry.path] = file
                descriptors[file.generationRelativePath] = descriptor
                observations[file.entry.path] = observation
            }
        }
        // Only generation members are copied; raw global publications and their
        // immutable witnesses continue to belong to the existing raw owner.
        guard plan.generationMembers.allSatisfy({ member in
            files[member.entry.path]?.entry == member.entry
                && files[member.entry.path]?.generationRelativePath == member.relativePath
        }) else { throw failure }
        self.members = .init(rootURL: rootURL,
            rootIdentity: .init(device: device, inode: inode), descriptors: descriptors,
            maximumMemberByteCount: Int64(MediaContractV1.sourceByteCountMaximum))
        self.files = files; self.observations = observations
        self.metadata = plan.metadata; self.rootIdentity = rootIdentity
    }

    func read(_ entry: V4BackupEntryV1, consume: (Data) throws -> Void) throws {
        guard let file = files[entry.path], file.entry == entry,
              let observation = observations[entry.path] else { throw BackupRestoreServiceError.invalidPackage }
        let writeEntry = StreamingArchiveWriteEntryV1(path: entry.path, mimeType: entry.mimeType,
            sourceRootURL: members.rootURL, sourceRelativePath: file.generationRelativePath,
            expectedSourceRootIdentity: rootIdentity, expectedUncompressedByteCount: Int64(entry.byteCount),
            expectedContentSHA256: entry.sha256, compression: .stored)
        let observer = StreamingArchiveService()
        guard try observer.sourceObservation(writeEntry) == observation else { throw BackupRestoreServiceError.invalidPackage }
        try members.readVerifiedChunks(file.generationRelativePath,
            expectedByteCount: Int64(entry.byteCount), expectedSHA256: entry.sha256,
            maximumByteCount: Int64(MediaContractV1.sourceByteCountMaximum), cancellation: .task,
            consume: consume)
        guard try observer.sourceObservation(writeEntry) == observation else { throw BackupRestoreServiceError.invalidPackage }
    }

    func metadataBytes(_ path: String) -> Data? { metadata[path] }
}

/// Exact current-only canonical files selected by authenticated composition.
/// Retains bounded descriptors and source observations, never an archive of Data.
/// The existing restore writer remains the only destination owner.
fileprivate struct RetainedCanonicalRestoreMembersV1: Sendable {
    private let members: ValidatedV4BackupMembersV1
    private let entries: [String: StreamingArchiveWriteEntryV1]
    private let observations: [String: StreamingArchiveSourceObservationV1]

    var keys: Set<String> { Set(entries.keys) }
    var byteCount: Int64 { entries.values.reduce(0) { $0 + $1.expectedUncompressedByteCount } }

    fileprivate init(root: URL, rootIdentity: StreamingArchiveRootIdentityV1,
        entries: [String: StreamingArchiveWriteEntryV1],
        snapshots: [String: StreamingArchiveSourceSnapshotV1],
        authorityCheck: () throws -> Void) throws {
        let failure = BackupRestoreServiceError.invalidRestoreAuthority
        let limits = StreamingArchiveLimitsV1.card17
        guard Set(entries.keys) == Set(snapshots.keys), entries.count <= limits.maximumEntryCount,
              let device = dev_t(exactly: rootIdentity.device),
              let inode = ino_t(exactly: rootIdentity.inode) else { throw failure }
        var descriptors: [String: ValidatedV4BackupMembersV1.Descriptor] = [:]
        var observations: [String: StreamingArchiveSourceObservationV1] = [:]
        let observer = StreamingArchiveService()
        var total: Int64 = 0
        for key in entries.keys.sorted() {
            try Task.checkCancellation()
            try authorityCheck()
            guard let entry = entries[key], entry.path == key, entry.sourceRootURL == root,
                  entry.expectedSourceRootIdentity == rootIdentity,
                  entry.expectedUncompressedByteCount >= 0,
                  entry.expectedUncompressedByteCount <= limits.maximumUncompressedEntryByteCount,
                  StoreMigrationCanonicalJSONV1.isLowercaseSHA256(entry.expectedContentSHA256)
            else { throw failure }
            let sum = total.addingReportingOverflow(entry.expectedUncompressedByteCount)
            guard !sum.overflow, sum.partialValue <= limits.maximumUncompressedAggregateByteCount
            else { throw failure }
            total = sum.partialValue
            let descriptor = ValidatedV4BackupMembersV1.Descriptor(
                byteCount: entry.expectedUncompressedByteCount, sha256: entry.expectedContentSHA256)
            guard descriptors.updateValue(descriptor, forKey: entry.sourceRelativePath) == nil
            else { throw failure }
            let observation = try observer.sourceObservation(entry)
            guard observation.file == snapshots[key], observation.file.linkCount == 1
            else { throw failure }
            observations[key] = observation
        }
        self.members = .init(rootURL: root, rootIdentity: .init(device: device, inode: inode),
            descriptors: descriptors, maximumMemberByteCount: limits.maximumUncompressedEntryByteCount)
        self.entries = entries
        self.observations = observations
        // Verify complete original hashes without retaining bytes during preparation.
        for key in entries.keys.sorted() {
            try read(key, authorityCheck: authorityCheck) { _ in }
        }
        try validateObservations(authorityCheck: authorityCheck)
    }

    func validateObservations(authorityCheck: () throws -> Void) throws {
        let observer = StreamingArchiveService()
        for key in entries.keys.sorted() {
            try Task.checkCancellation()
            try authorityCheck()
            guard let entry = entries[key], let original = observations[key],
                  try observer.sourceObservation(entry) == original else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
        }
        try authorityCheck()
    }

    private func read(_ path: String, authorityCheck: () throws -> Void,
        consume: (Data) throws -> Void) throws {
        guard let entry = entries[path], let original = observations[path] else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let observer = StreamingArchiveService()
        try authorityCheck()
        guard try observer.sourceObservation(entry) == original else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        try members.readVerifiedChunks(entry.sourceRelativePath,
            expectedByteCount: entry.expectedUncompressedByteCount,
            expectedSHA256: entry.expectedContentSHA256,
            maximumByteCount: StreamingArchiveLimitsV1.card17.maximumUncompressedEntryByteCount,
            cancellation: .task) { chunk in
                try authorityCheck()
                try consume(chunk)
            }
        try authorityCheck()
        guard try observer.sourceObservation(entry) == original else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
    }

    /// At most one bounded member lives in memory for the incumbent writeExact.
    func bytes(_ path: String, authorityCheck: () throws -> Void) throws -> Data? {
        guard entries[path] != nil else { return nil }
        var data = Data()
        try read(path, authorityCheck: authorityCheck) { data.append($0) }
        return data
    }
}

enum CheckRunnerPhotoRestoreMemberSourceV1: Sendable {
    case package(ValidatedV4BackupMembersV1)
    case retained(CheckRunnerPhotoRestoreRetainedMembersV1)

    func read(_ entry: V4BackupEntryV1,
        maximumByteCount: Int64 = Int64(MediaContractV1.sourceByteCountMaximum),
        consume: (Data) throws -> Void) throws {
        guard entry.byteCount >= 0, Int64(entry.byteCount) <= maximumByteCount else {
            throw BackupRestoreServiceError.invalidPackage
        }
        switch self {
        case .package(let members):
            try members.readVerifiedChunks(entry.path, expectedByteCount: Int64(entry.byteCount),
                expectedSHA256: entry.sha256,
                maximumByteCount: maximumByteCount, cancellation: .task, consume: consume)
        case .retained(let members): try members.read(entry, consume: consume)
        }
    }

    func metadataBytes(_ path: String) -> Data? {
        switch self {
        case .package(let members): members[path]
        case .retained(let members): members.metadataBytes(path)
        }
    }
}

/// Generic staging remains under the incumbent staging owner, with the
/// released generic limit and canonical archive path independent of photo limits.
enum CheckRunnerPhotoRestoreGenericStageV1 {
    static func payloadEntry(_ item: AttachmentStagingItemV1) throws -> V4BackupEntryV1 {
        guard item.state == .readyLocal || item.state == .committed,
              let count = item.actualByteCount, count > 0,
              count <= Int64(FieldDraftLimitsV1.maximumPayloadBytes),
              let digest = item.contentDigest, digest.algorithm == .sha256,
              StoreMigrationCanonicalJSONV1.isLowercaseSHA256(digest.hexadecimalValue) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        return .init(byteCount: Int(count), mimeType: "application/octet-stream",
            path: "draft-staging/\(item.draftID.uuidString.lowercased())/\(item.stageID.uuidString.lowercased()).bin",
            sha256: digest.hexadecimalValue)
    }

    static func plannedReceipt(_ transition: DraftPhotoRestoreRawTransitionV1,
        restoreID: UUID, workspaceID: WorkspaceID, publishedAt: Date) throws
        -> DraftAttachmentRestorePublicationReceiptV1? {
        let ids = Set(transition.genericStageIDs)
        guard !ids.isEmpty else { return nil }
        let entries = transition.after.entries.filter { ids.contains($0.item.stageID) }
        guard entries.count == ids.count else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        let manifest = try DraftAttachmentStagingManifestV1(entries: entries)
        // This is a prebound disposition, not evidence of a public effect.
        // Only the saved combined inode receipt and kernel decision authorize
        // publication or cleanup; the generic receipt never authorizes deletion.
        return try .init(restoreID: restoreID, workspaceID: workspaceID,
            sourceManifestSHA256: manifest.manifestSHA256,
            adoptedStageIDs: transition.newStageIDs.filter { ids.contains($0) },
            reusedStageIDs: transition.reusedStageIDs.filter { ids.contains($0) },
            publishedAt: publishedAt)
    }
}

/// Minted only by the incumbent restore service after canonical validation and
/// creation of its private staging generation. Media publication keeps this
/// original root and package binding across the actor hop.
struct CheckRunnerPhotoRestoreGenerationAuthorityV1: Sendable {
    let generationID: UUID
    let rootURL: URL
    let rootIdentity: ReportPDFAnchoredFile.RootIdentity
    let children: [CheckRunnerPhotoBackupHistoryChildV1]
    let plan: CheckRunnerPhotoBackupRestorePlanV1
    let memberSource: CheckRunnerPhotoRestoreMemberSourceV1
    let membersToMaterialize: [CheckRunnerPhotoBackupRestorePlanV1.GenerationMember]

    fileprivate init(generationID: UUID, rootURL: URL,
        rootIdentity: ReportPDFAnchoredFile.RootIdentity,
        children: [CheckRunnerPhotoBackupHistoryChildV1],
        plan: CheckRunnerPhotoBackupRestorePlanV1, memberSource: CheckRunnerPhotoRestoreMemberSourceV1,
        membersToMaterialize: [CheckRunnerPhotoBackupRestorePlanV1.GenerationMember]? = nil) {
        self.membersToMaterialize = membersToMaterialize ?? plan.generationMembers
        self.generationID = generationID
        self.rootURL = rootURL
        self.rootIdentity = rootIdentity
        self.children = children
        self.plan = plan
        self.memberSource = memberSource
    }
}

/// The clone owner derives this closed transfer from the already rebound
/// canonical destination. It does not confer authority over operational drafts.
struct ConfigurationCloneFinalMediaGenerationAuthorityV1: Sendable {
    let generationID: UUID
    let rootURL: URL
    let rootIdentity: ReportPDFAnchoredFile.RootIdentity
    let members: [CheckRunnerPhotoBackupRestorePlanV1.GenerationMember]
    let memberSource: CheckRunnerPhotoRestoreMemberSourceV1
    let maximumMemberByteCount: Int64

    fileprivate init(generationID: UUID, rootURL: URL,
        rootIdentity: ReportPDFAnchoredFile.RootIdentity,
        members: [CheckRunnerPhotoBackupRestorePlanV1.GenerationMember],
        memberSource: CheckRunnerPhotoRestoreMemberSourceV1, maximumMemberByteCount: Int64) {
        self.generationID = generationID; self.rootURL = rootURL
        self.rootIdentity = rootIdentity; self.members = members
        self.memberSource = memberSource
        self.maximumMemberByteCount = maximumMemberByteCount
    }
}

/// Minted only by the sole restore owner after authenticating the durable plan.
/// This is physical recovery authority, never an accepted workspace receipt.
struct DraftConfigurationCloneRetirementAuthorityV1: Sendable {
    let plan: DraftConfigurationCloneRetirementPlanV1
    let bindingSHA256: String
    let applicationSupportURL: URL

    fileprivate init(core: ConfigurationCloneRetirementCoreV1, applicationSupportURL: URL) throws {
        try core.validate()
        plan = core.plan
        bindingSHA256 = try core.sha256()
        self.applicationSupportURL = applicationSupportURL
    }
}

struct DraftConfigurationCloneRetirementPermitV1: Sendable {
    enum Disposition: Equatable, Sendable { case quarantine, rollback, retire }
    let authority: DraftConfigurationCloneRetirementAuthorityV1
    let ownershipSHA256: String
    let disposition: Disposition

    /// Pointer/intent/retirement validation is performed under G by the caller
    /// in this file before this value enters the incumbent adapter's R scope.
    fileprivate init(binding: ConfigurationCloneRetirementBindingV1,
        applicationSupportURL: URL, disposition: Disposition) throws {
        try binding.validate()
        guard let ownership = binding.ownership else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        authority = try .init(core: binding.core, applicationSupportURL: applicationSupportURL)
        ownershipSHA256 = try ownership.sha256()
        self.disposition = disposition
    }
}

/// The schema-4 intent commits to this immutable preimage. Its embedded intent
/// uses the original schema-3 bytes so the hash has no circular dependency.
fileprivate struct ConfigurationCloneRetirementCoreV1: Codable, Equatable, Sendable {
    let schemaVersion: Int
    let originalIntentData: Data
    let plan: DraftConfigurationCloneRetirementPlanV1
    let currentRecordsSHA256: String
    let destinationRecordsSHA256: String
    let sourceManifestSHA256: String
    let currentMembers: CheckRunnerPhotoRestoreMemberBindingV1

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case schemaVersion, originalIntentData, plan, currentRecordsSHA256
        case destinationRecordsSHA256, sourceManifestSHA256, currentMembers
    }

    init(intent: RestoreIntentV1, plan: DraftConfigurationCloneRetirementPlanV1,
        currentRecordsSHA256: String, destinationRecordsSHA256: String,
        sourceManifestSHA256: String, currentMembers: CheckRunnerPhotoRestoreMemberBindingV1) throws {
        schemaVersion = 1
        originalIntentData = try RestoreIntentCodecV1.encode(intent)
        self.plan = plan
        self.currentRecordsSHA256 = currentRecordsSHA256
        self.destinationRecordsSHA256 = destinationRecordsSHA256
        self.sourceManifestSHA256 = sourceManifestSHA256
        self.currentMembers = currentMembers
        try validate()
    }

    init(from decoder: Decoder) throws {
        try ClosedContractDecodingV1.rejectUnknownKeys(decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)))
        let values = try decoder.container(keyedBy: CodingKeys.self)
        schemaVersion = try values.decode(Int.self, forKey: .schemaVersion)
        originalIntentData = try values.decode(Data.self, forKey: .originalIntentData)
        plan = try values.decode(DraftConfigurationCloneRetirementPlanV1.self, forKey: .plan)
        currentRecordsSHA256 = try values.decode(String.self, forKey: .currentRecordsSHA256)
        destinationRecordsSHA256 = try values.decode(String.self, forKey: .destinationRecordsSHA256)
        sourceManifestSHA256 = try values.decode(String.self, forKey: .sourceManifestSHA256)
        currentMembers = try values.decode(CheckRunnerPhotoRestoreMemberBindingV1.self, forKey: .currentMembers)
        try validate()
    }

    var originalIntent: RestoreIntentV1 {
        get throws { try RestoreIntentCodecV1.decode(originalIntentData) }
    }

    func validate() throws {
        try plan.validate()
        let intent = try originalIntent
        guard schemaVersion == 1, intent.schemaVersion == 3,
              intent.phase == .prepared, intent.cloneRetirementPlanSHA256 == nil,
              let identity = intent.identity, identity.mode == .clone,
              intent.restoreID == plan.restoreID,
              identity.oldPointer.workspaceID == plan.workspaceID.rawValue,
              currentMembers.source.workspaceID == identity.oldPointer.workspaceID,
              currentMembers.source.replicaID == identity.oldPointer.replicaID,
              currentMembers.source.sourceGenerationID == intent.oldGenerationID,
              [currentRecordsSHA256, destinationRecordsSHA256, sourceManifestSHA256]
                .allSatisfy(StoreMigrationCanonicalJSONV1.isLowercaseSHA256) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
    }

    func sha256() throws -> String {
        try validate()
        return try StoreMigrationCanonicalJSONV1.digest(self)
    }

    func boundIntent() throws -> RestoreIntentV1 {
        let original = try originalIntent
        guard let identity = original.identity, let timestamp = original.replacementTimestampMilliseconds else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        return RestoreIntentV1(identity: identity, restoreID: original.restoreID,
            replacementTimestampMilliseconds: timestamp, cloneRetirementPlanSHA256: try sha256())
    }

    func requireIntent(_ intent: RestoreIntentV1) throws {
        guard try intent == boundIntent().advancing(to: intent.phase) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
    }

    func resolveCurrent(in records: V4BackupRecordsV1) throws -> CheckRunnerPhotoBackupRestorePlanV1 {
        guard try BackupCanonicalEncoderV1().encodeRecords(records).sha256 == currentRecordsSHA256 else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let history = try CheckRunnerPhotoBackupHistoryV1.project(source: currentMembers.source, records: records)
        let photoPlan = try currentMembers.resolve(history: history)
        let stages: [AttachmentStagingItemV1] = try records.fieldDrafts.compactMap { row in
            guard row.kind == .stagingItem else { return nil }
            return try FieldDraftCanonicalCodecV1.decode(AttachmentStagingItemV1.self, from: row.canonicalData)
        }
        let canonicalStages = Dictionary(uniqueKeysWithValues: stages.map { ($0.stageID, $0) })
        let physicalStages = Dictionary(uniqueKeysWithValues: plan.before.entries.map { ($0.item.stageID, $0) })
        let rawStages = Dictionary(uniqueKeysWithValues: photoPlan.rawPublications.map { ($0.physicalEntry.entry.item.stageID, $0) })
        guard canonicalStages.count == stages.count, Set(canonicalStages.keys) == Set(physicalStages.keys) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let nodes = Dictionary(uniqueKeysWithValues: plan.beforeNodes.map { ($0.path, $0) })
        var expectedWitnessPaths = Set<String>()
        var requiredParents = Set<String>()
        for stage in stages {
            guard let entry = physicalStages[stage.stageID] else { throw BackupRestoreServiceError.invalidRestoreAuthority }
            if stage.state != .orphanQuarantined {
                requiredParents.insert("draft-\(stage.draftID.uuidString.lowercased())")
            }
            if let raw = rawStages[stage.stageID] {
                let witnessPath = String(entry.relativeDataPath.dropLast("payload.bin".count)) + "raw-publication.json"
                expectedWitnessPaths.insert(witnessPath)
                guard entry == raw.physicalEntry.entry,
                      nodes[entry.relativeDataPath]?.byteCount == Int64(raw.payload.byteCount),
                      nodes[entry.relativeDataPath]?.sha256 == raw.payload.sha256,
                      nodes[witnessPath]?.byteCount == Int64(raw.witness.byteCount),
                      nodes[witnessPath]?.sha256 == raw.witness.sha256 else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
            } else if entry.item != stage { throw BackupRestoreServiceError.invalidRestoreAuthority }
        }
        let optionalParents = Set(history.children.filter { $0.raw == nil }.map {
            "draft-\($0.payload.childDraftID.uuidString.lowercased())"
        })
        let actualParents = Set(plan.movedRoots).subtracting(["quarantine"])
        guard requiredParents.isSubset(of: actualParents),
              actualParents.isSubset(of: requiredParents.union(optionalParents)),
              Set(plan.beforeNodes.filter { $0.path.hasSuffix("/raw-publication.json") }.map(\.path)) == expectedWitnessPaths else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        return photoPlan
    }
}

/// Physical placement is inferred only from the closed plan and original inode
/// claims. A terminal value survives removal of the base intent so cold cleanup
/// cannot orphan its recovery authority between the two metadata removals.
fileprivate struct ConfigurationCloneRetirementBindingV1: Codable, Equatable, Sendable {
    enum Completion: String, Codable, Sendable { case active, rolledBack, retired }
    let schemaVersion: Int
    let core: ConfigurationCloneRetirementCoreV1
    let ownership: DraftConfigurationCloneRetirementOwnershipV1?
    let completion: Completion

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case schemaVersion, core, ownership, completion
    }

    init(core: ConfigurationCloneRetirementCoreV1,
        ownership: DraftConfigurationCloneRetirementOwnershipV1? = nil,
        completion: Completion = .active) throws {
        schemaVersion = 1
        self.core = core; self.ownership = ownership; self.completion = completion
        try validate()
    }

    init(from decoder: Decoder) throws {
        try ClosedContractDecodingV1.rejectUnknownKeys(decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)))
        let values = try decoder.container(keyedBy: CodingKeys.self)
        schemaVersion = try values.decode(Int.self, forKey: .schemaVersion)
        core = try values.decode(ConfigurationCloneRetirementCoreV1.self, forKey: .core)
        ownership = try values.decodeIfPresent(DraftConfigurationCloneRetirementOwnershipV1.self, forKey: .ownership)
        completion = try values.decode(Completion.self, forKey: .completion)
        try validate()
    }

    func validate() throws {
        try core.validate()
        try ownership?.validate()
        guard schemaVersion == 1, ownership.map({ $0.plan == core.plan }) ?? true,
              completion != .retired || ownership != nil else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
    }

    func isImmediateSuccessor(of previous: Self) -> Bool {
        guard schemaVersion == previous.schemaVersion, core == previous.core,
              previous.completion == .active else { return false }
        if previous.ownership == nil, ownership != nil { return completion == .active }
        return ownership == previous.ownership && completion != .active
    }

    func canonicalData() throws -> Data {
        try validate()
        return try StoreMigrationCanonicalJSONV1.encode(self)
    }
}

fileprivate enum ConfigurationCloneEmptyStagingProofV1 {
    case existing(DraftPhotoBackupPreparedVerificationV1)
    case absent(DraftPhotoBackupAbsentRootPreparedVerificationV1)

    func withVerificationLock<T>(_ body: () throws -> T) throws -> T {
        switch self {
        case .existing(let proof): try proof.withVerificationLock(body)
        case .absent(let proof): try proof.withVerificationLock(body)
        }
    }
}

/// Keeps the original empty-root proof while the final target manifest is
/// bound, then carries that exact restore identity through cold/async cleanup.
fileprivate struct ConfigurationCloneEmptyStagingGuardV1 {
    let originalIntent: RestoreIntentV1
    let restoreID: UUID
    let identity: RestoreIdentityV1
    let proof: ConfigurationCloneEmptyStagingProofV1

    init(intent: RestoreIntentV1, proof: ConfigurationCloneEmptyStagingProofV1) throws {
        guard RestoreIntentCodecV1.valid(intent), let identity = intent.identity,
              identity.mode == .clone else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        self.originalIntent = intent
        self.restoreID = intent.restoreID; self.identity = identity; self.proof = proof
    }

    func requireIntent(_ intent: RestoreIntentV1) throws {
        guard RestoreIntentCodecV1.valid(intent), intent.restoreID == restoreID,
              intent == originalIntent.advancing(to: intent.phase),
              intent.identity == identity,
              intent.oldGenerationID == identity.oldPointer.generationID,
              intent.newGenerationID == identity.targetPointer.generationID else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
    }
}

