    func myDayTargetReferences(
        requiredBy plans: [MyDayPlanV1],
        in records: V4BackupRecordsV1
    ) throws -> [MyDayEligibleReferenceV1] {
        let required = Set(plans.flatMap { $0.items.map(\.reference.stableKey) })
        guard !required.isEmpty else { return [] }
        var candidates: [MyDayEligibleReferenceV1] = []
        candidates += try records.workPackets.compactMap { record in
            guard record.kind == .manifest else { return nil }
            let value = try WorkPacketCanonicalCodecV1.decode(
                WorkPacketManifestV1.self, from: record.canonicalData
            )
            return .workPacket(try WorkPacketManifestReferenceV1(value))
        }
        candidates += try records.guidedSurveys.compactMap { record in
            guard record.kind == .session else { return nil }
            let value = try SurveySessionCanonicalCodecV1.decode(
                SurveySessionV1.self, from: record.canonicalData
            )
            return .roundSession(
                workspaceID: value.workspaceID, sessionID: value.sessionID,
                revision: value.revision, sessionSHA256: value.sessionSHA256
            )
        }
        candidates += try records.schedules.compactMap { record in
            guard record.kind == .occurrenceHistory else { return nil }
            let value = try ScheduleCanonicalCodecV1.decode(
                OccurrenceHistoryEventV1.self, from: record.canonicalData
            )
            return .scheduleOccurrence(
                try C34OccurrenceNavigationAnchorV1(event: value),
                sourceEventSHA256: value.eventSHA256
            )
        }
        candidates += try records.fieldDrafts.compactMap { record in
            guard record.kind == .checkpoint else { return nil }
            let value = try FieldDraftCanonicalCodecV1.decode(
                FieldDraftCheckpointV1.self, from: record.canonicalData
            )
            return .resumableDraft(
                workspaceID: value.workspaceID, draftID: value.draftID,
                revision: value.draftRevision, checkpointSHA256: value.checkpointSHA256,
                anchor: value.resumeAnchor
            )
        }
        let grouped = Dictionary(grouping: candidates, by: \.stableKey)
        return try required.sorted().map { key in
            guard let values = grouped[key],
                  let latest = values.max(by: { $0.sourceRevision < $1.sourceRevision }),
                  latest.stableKey == key else { throw MyDayFailureV1.missingSource }
            try latest.validate()
            return latest
        }
    }

    func recordsForMaterialization(
        _ records: V4BackupRecordsV1,
        members: ValidatedV4BackupMembersV1,
        identityDecision: RestoreIdentityV1?,
        legacyWorkspaceID: UUID,
        partsStockOperationID: UUID,
        currentOriginalRecords: V4BackupRecordsV1? = nil,
        incomingOriginalRecords: V4BackupRecordsV1? = nil
    ) throws -> V4BackupRecordsV1 {
#if DEBUG
        var materializationPhase = "before-c55-initial-admission"
#endif
        do {
        let currentOriginal = currentOriginalRecords ?? records
        let incomingOriginal = incomingOriginalRecords ?? records
        let roundProjection: RoundSessionReplacementCommandProjectionV1.Projection?
        if let identityDecision, identityDecision.mode == .replaceExisting,
           identityDecision.source.workspaceID != identityDecision.targetPointer.workspaceID,
           records.recordsSchemaVersion >= C05RoundSessionBackupEnrollmentV1.recordsSchemaVersion {
            guard let sourceWorkspaceID = identityDecision.source.workspaceID,
                  let sourceHistory = incomingOriginal.mutationHistory else {
                throw BackupRestoreServiceError.invalidPackage
            }
            let source = try ReferenceOwnerReplacementSourceV1.source(
                workspaceID: WorkspaceID(rawValue: sourceWorkspaceID), history: sourceHistory)
            let projected = try RoundSessionReplacementCommandProjectionV1.project(
                source: source, identity: identityDecision)
            let originals: [RoundSessionV1] = try projected.commands.map { command in
                guard case let .applyRoundSession(mutation) = command.source.envelope.command else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                return mutation.session
            }
            func ordered(_ rows: [RoundSessionV1]) -> [RoundSessionV1] {
                rows.sorted {
                    if $0.sessionID != $1.sessionID {
                        return $0.sessionID.uuidString < $1.sessionID.uuidString
                    }
                    return $0.revision < $1.revision
                }
            }
            guard ordered(originals) == ordered(incomingOriginal.roundSessions),
                  ordered(records.roundSessions) == ordered(originals) else {
                throw BackupRestoreServiceError.invalidPackage
            }
            roundProjection = projected
        } else { roundProjection = nil }
        let roundRows: [RoundSessionV1] = roundProjection.map {
            $0.commands.map { $0.mutation.session }
        } ?? records.roundSessions
        if records.recordsSchemaVersion >= C47ActivityContractPersistenceBoundaryV2.recordsSchemaVersion {
            _ = try records.validateC47ActivityContracts()
            try validateResolvedActivityContracts(in: records, members: members)
        } else if !records.activityContracts.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C49BackupEnrollmentV1.recordsSchemaVersion {
            _ = try records.validateC49WorkResources()
        } else if !records.workResources.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C57MyDayBackupEnrollmentV1.recordsSchemaVersion {
            do {
                try C57MyDayBackupEnrollmentV1.validate(records)
                _ = try C57MyDayRestoreIdentityBoundaryV1.canonicalTruth(
                    plans: records.myDayPlans,
                    carryovers: records.myDayCarryoverReceipts,
                    nonactivePlanReferences: records.nonactivePlanReferences,
                    mode: identityDecision?.mode ?? .replaceExisting
                )
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        } else if !records.myDayPlans.isEmpty || !records.myDayCarryoverReceipts.isEmpty
                    || !records.nonactivePlanReferences.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C05EvidenceMetadataBackupEnrollmentV1.recordsSchemaVersion {
            do {
                try C05EvidenceMetadataBackupEnrollmentV1.validate(records)
                try C04ShopReportProfileBackupEnrollmentV1.validate(records)
                try C05RoundSessionBackupEnrollmentV1.validate(records)
                try C05EvidenceMetadataRestoreIdentityBoundaryV1.validate(
                    records,
                    identity: identityDecision
                )
                let workspaceID = C05EvidenceMetadataRestoreIdentityBoundaryV1.expectedWorkspaceID(
                    identity: identityDecision,
                    legacyDestination: legacyWorkspaceID
                )
                guard records.evidenceAssociationEvents.allSatisfy({
                    $0.workspaceID == workspaceID.uuidString.lowercased()
                }), records.evidenceSequenceRevisions.allSatisfy({
                    $0.workspaceID.rawValue == workspaceID
                }) else { throw attributedRestoreAuthorityFailureV1(line: #line) }
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        } else if !records.evidenceAssociationEvents.isEmpty
                    || !records.evidenceSequenceRevisions.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C04ShopReportProfileBackupEnrollmentV1.recordsSchemaVersion {
            do {
                try C04ShopReportProfileBackupEnrollmentV1.validate(records)
                let expectedWorkspaceID = identityDecision?.targetPointer.workspaceID
                    ?? legacyWorkspaceID
                let profiles: [ShopReportProfileV1]
                if let identityDecision {
                    profiles = try C04ShopReportProfileRestoreIdentityBoundaryV1.rebinding(
                        records.shopReportProfiles,
                        identity: identityDecision
                    )
                } else {
                    profiles = records.shopReportProfiles
                }
                guard profiles.allSatisfy({
                    $0.workspaceID.rawValue == expectedWorkspaceID
                }) else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        } else if !records.shopReportProfiles.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C05RoundSessionBackupEnrollmentV1.recordsSchemaVersion {
            do {
                try C05RoundSessionBackupEnrollmentV1.validate(records)
                let expectedWorkspaceID = identityDecision?.targetPointer.workspaceID
                    ?? legacyWorkspaceID
                let sessions: [RoundSessionV1]
                if let identityDecision {
                    sessions = try C05RoundSessionRestoreIdentityBoundaryV1.rebinding(
                        roundRows,
                        identity: identityDecision
                    )
                } else {
                    sessions = records.roundSessions
                }
                guard sessions.allSatisfy({
                    $0.workspaceID.rawValue == expectedWorkspaceID
                }) else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        } else if !records.roundSessions.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C53ServiceReliabilityBackupEnrollmentV1.recordsSchemaVersion {
            do {
                let expectedWorkspaceID: UUID?
                if let decision = identityDecision {
                    switch decision.mode {
                    case .clone, .fork:
                        expectedWorkspaceID = decision.source.workspaceID
                    case .emptyInstall, .replaceExisting:
                        expectedWorkspaceID = decision.targetPointer.workspaceID
                    }
                } else {
                    expectedWorkspaceID = legacyWorkspaceID
                }
                let values = try C53ServiceReliabilityBackupEnrollmentV1.canonicalRows(
                    from: records, workspaceID: expectedWorkspaceID
                )
                guard values.incidents.count == records.serviceReliabilityIncidents.count,
                      values.impactSegments.count == records.serviceImpactSegments.count,
                      values.causeAssertions.count == records.serviceCauseAssertions.count,
                      values.remedyAssertions.count == records.serviceRemedyAssertions.count,
                      values.repairIntervals.count == records.serviceRepairIntervals.count,
                      values.restorationAssertions.count == records.serviceRestorationAssertions.count,
                      values.qualifiedExposures.count == records.qualifiedServiceExposures.count,
                      values.receipts.count == records.serviceReliabilityReceipts.count else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        } else if !records.serviceReliabilityIncidents.isEmpty
                    || !records.serviceImpactSegments.isEmpty
                    || !records.serviceCauseAssertions.isEmpty
                    || !records.serviceRemedyAssertions.isEmpty
                    || !records.serviceRepairIntervals.isEmpty
                    || !records.serviceRestorationAssertions.isEmpty
                    || !records.qualifiedServiceExposures.isEmpty
                    || !records.serviceReliabilityReceipts.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if records.recordsSchemaVersion >= C55PartsStockBackupEnrollmentV1.recordsSchemaVersion {
#if DEBUG
            FileHandle.standardError.write(Data("C55 restore phase=initial-admission-before\n".utf8))
#endif
            do {
                let isCrossWorkspaceReplacement = identityDecision?.mode == .replaceExisting
                    && identityDecision?.source.workspaceID
                        != identityDecision?.targetPointer.workspaceID
                let sourceRecords = isCrossWorkspaceReplacement ? incomingOriginal : records
                let sourceWorkspaceID: UUID
                if isCrossWorkspaceReplacement {
                    guard let originalWorkspaceID = identityDecision?.source.workspaceID else {
                        throw BackupRestoreServiceError.invalidPackage
                    }
                    sourceWorkspaceID = originalWorkspaceID
                } else {
                    sourceWorkspaceID = identityDecision?.source.workspaceID ?? legacyWorkspaceID
                }
                try C55PartsStockBackupImportBoundaryV1.validate(
                    sourceRecords,
                    workspaceID: WorkspaceID(rawValue: sourceWorkspaceID)
                )
#if DEBUG
                FileHandle.standardError.write(Data("C55 restore phase=initial-admission-after\n".utf8))
#endif
            } catch {
#if DEBUG
                FileHandle.standardError.write(Data((
                    "C55 restore failure phase=initial-admission "
                        + "type=\(String(reflecting: type(of: error))) error=\(error)\n"
                ).utf8))
#endif
                throw BackupRestoreServiceError.invalidPackage
            }
        } else if records.partsStockSnapshot != nil {
            throw BackupRestoreServiceError.invalidPackage
        }
#if DEBUG
        materializationPhase = "c52-admission"
#endif
        if records.recordsSchemaVersion >= C52ServiceRequestReplaceRestoreBoundaryV1.recordsSchemaVersion {
            do {
                let expectedWorkspaceID: UUID?
                if let decision=identityDecision {
                    expectedWorkspaceID=C52ServiceRequestRestoreIdentityPolicyV1.preservesCanonicalWorkspaceBinding(for:decision.mode)
                        ? decision.targetPointer.workspaceID : decision.source.workspaceID
                } else {
                    expectedWorkspaceID=legacyWorkspaceID
                }
#if DEBUG
                materializationPhase = "c52-canonical-rows"
#endif
                let values = try C52ServiceRequestBackupEnrollmentV1.canonicalRows(
                    from: records, workspaceID: expectedWorkspaceID
                )
                guard values.records.count == records.serviceRequests.count,
                      values.dispositions.count == records.serviceRequestDispositionEvents.count,
                      values.workLinks.count == records.serviceRequestWorkLinkEvents.count else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        } else if !records.serviceRequests.isEmpty
                    || !records.serviceRequestDispositionEvents.isEmpty
                    || !records.serviceRequestWorkLinkEvents.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
#if DEBUG
        materializationPhase = "c46-admission"
#endif
        if records.recordsSchemaVersion >= OperationalContactPersistenceEnrollmentV1.recordsSchemaVersion {
            _ = try records.validateC46OperationalContacts()
        } else if !records.operationalContacts.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
#if DEBUG
        materializationPhase = "observation-time-normalization"
#endif
        var normalized = try recordsWithObservationAndTime(records)
            .replacingOperationalContacts(records.operationalContacts)
#if DEBUG
        materializationPhase = "requirement-assurance-normalization"
#endif
        normalized = try recordsWithRequirementAssurance(
            normalized,
            workspaceID: identityDecision.map { $0.targetPointer.workspaceID }
                ?? legacyWorkspaceID
        )
#if DEBUG
        materializationPhase = "placement-pose-admission"
#endif
        if !normalized.placementPoses.isEmpty {
            let destinationWorkspaceID = WorkspaceID(
                rawValue: identityDecision?.targetPointer.workspaceID
                    ?? legacyWorkspaceID
            )
            if let identityDecision {
#if DEBUG
                materializationPhase = "placement-pose-rebind"
#endif
                normalized = try rebindingPlacementPoses(
                    in: normalized,
                    identity: identityDecision,
                    workspaceID: destinationWorkspaceID
                )
            } else {
                guard normalized.placementPoses.allSatisfy({
                    $0.workspaceID == destinationWorkspaceID.rawValue
                }) else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                _ = try PlacementPoseBackupRecordSetV1.decode(
                    normalized.placementPoses
                )
            }
        }
        if normalized.recordsSchemaVersion
            >= AssetLabelPersistenceEnrollmentV1.recordsSchemaVersion {
#if DEBUG
            materializationPhase = "c45-validation"
#endif
            _ = try normalized.validateC45AcceptedLabelSnapshots()
        }
        if let identityDecision,
           identityDecision.mode == .clone || identityDecision.mode == .fork {
#if DEBUG
            materializationPhase = "accepted-label-rebind"
#endif
            normalized = normalized.replacingAcceptedLabelGenerationSnapshots(
                try rebindingAcceptedLabelSnapshots(
                    normalized.acceptedLabelGenerationSnapshots,
                    identity: identityDecision
                )
            )
        }
        if normalized.recordsSchemaVersion >= 5,
           let identityDecision {
#if DEBUG
            materializationPhase = "source-assurance-previews"
#endif
            let sourcePreviews = try sourceAssurancePreviews(
                records: normalized, members: members
            )
#if DEBUG
            materializationPhase = "location-migration-rebind"
#endif
            normalized = try rebindingLocationMigrationReceipt(
                in: normalized,
                identity: identityDecision,
                workspaceID: WorkspaceID(
                    rawValue: identityDecision.targetPointer.workspaceID
                ),
                generationID: identityDecision.targetPointer.generationID,
                sourceAssurancePreviews: sourcePreviews,
                members: members
            )
        }
        if let identityDecision,
           identityDecision.mode == .replaceExisting,
           identityDecision.source.workspaceID
            != identityDecision.targetPointer.workspaceID,
           normalized.recordsSchemaVersion
            >= OperationalContactPersistenceEnrollmentV1.recordsSchemaVersion {
#if DEBUG
            materializationPhase = "c46-cross-workspace-rebind"
#endif
            normalized = try rebindingCrossWorkspaceReplacementOperationalContacts(
                source: records,
                destination: normalized,
                identity: identityDecision
            )
#if DEBUG
            materializationPhase = "c46-rebound-validation"
#endif
            _ = try normalized.validateC46OperationalContacts()
        }
        var historicReplicas = RestoreHistoricReplicaScope()
        if let identityDecision,
           normalized.recordsSchemaVersion >= C47ActivityContractPersistenceBoundaryV2.recordsSchemaVersion {
#if DEBUG
            materializationPhase = "c47-rebind"
#endif
            normalized = try rebindingActivityContracts(
                in: normalized,
                sourceRecords: records,
                identity: identityDecision,
                historicReplicas: &historicReplicas
            )
        } else if normalized.recordsSchemaVersion >= C47ActivityContractPersistenceBoundaryV2.recordsSchemaVersion {
#if DEBUG
            materializationPhase = "c47-validation"
#endif
            _ = try normalized.validateC47ActivityContracts()
        }
        if normalized.recordsSchemaVersion
            >= C47ActivityContractPersistenceBoundaryV2.recordsSchemaVersion {
            // `rebindingActivityContracts` proves every source-to-target
            // digest and subject mapping while both representations are in
            // scope, then validates the rebound canonical closure. Do not run
            // the live-writer `validateResolved` rule on that target: only the
            // restore boundary may introduce its cross-workspace provenance.
#if DEBUG
            materializationPhase = "c47-validation"
#endif
            _ = try normalized.validateC47ActivityContracts()
        }
        if let identityDecision,
           normalized.recordsSchemaVersion >= C49BackupEnrollmentV1.recordsSchemaVersion,
           identityDecision.source.workspaceID != identityDecision.targetPointer.workspaceID {
            if identityDecision.mode == .replaceExisting,
               normalized.recordsSchemaVersion
                    >= C55PartsStockBackupEnrollmentV1.recordsSchemaVersion {
#if DEBUG
                materializationPhase = "c55-cross-workspace-rebind"
#endif
                normalized = try rebindingCrossWorkspacePartsStockReplacement(
                    in: normalized,
                    currentOriginal: currentOriginal,
                    incomingOriginal: incomingOriginal,
                    identity: identityDecision,
                    historicReplicas: &historicReplicas,
                    roundProjection: roundProjection
                )
            } else {
                normalized = try rebindingWorkResources(
                    in: normalized,
                    sourceRecords: records,
                    identity: identityDecision,
                    partsStockOperationID: partsStockOperationID,
                    historicReplicas: &historicReplicas
                )
            }
        } else if normalized.recordsSchemaVersion >= C49BackupEnrollmentV1.recordsSchemaVersion {
            _ = try normalized.validateC49WorkResources()
        }
        if records.recordsSchemaVersion >= C52ServiceRequestReplaceRestoreBoundaryV1.recordsSchemaVersion,
           let identityDecision {
#if DEBUG
            materializationPhase = "c52-rebound-identity-policy"
#endif
            do {
                // The policy also validates C55 against its destination. Run
                // it after stock projection, while still preparing values.
                try C52ServiceRequestRestoreIdentityPolicyV1.validate(normalized, identity: identityDecision)
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw BackupRestoreServiceError.invalidPackage }
        }
        if let identityDecision,
           identityDecision.mode == .replaceExisting,
           identityDecision.source.workspaceID
            == identityDecision.targetPointer.workspaceID,
           normalized.recordsSchemaVersion
            >= OperationalContactPersistenceEnrollmentV1.recordsSchemaVersion {
            guard normalized.operationalContacts == records.operationalContacts else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            // Re-run the complete row-to-journal receipt closure after every
            // other materialization normalization has finished. A replacement
            // is valid only while the preserved canonical contact bytes still
            // match their archived applyOperationalContact envelopes.
            _ = try normalized.validateC46OperationalContacts()
        }
        if records.recordsSchemaVersion >= C53ServiceReliabilityBackupEnrollmentV1.recordsSchemaVersion {
            do {
                let expectedWorkspaceID:UUID?
                if let identityDecision {
                    expectedWorkspaceID = identityDecision.mode == .clone || identityDecision.mode == .fork
                        ? identityDecision.source.workspaceID
                        : identityDecision.targetPointer.workspaceID
                } else {
                    expectedWorkspaceID = legacyWorkspaceID
                }
                let rows=try C53ServiceReliabilityBackupEnrollmentV1.canonicalRows(
                    from:records,
                    workspaceID:expectedWorkspaceID
                )
                normalized=try normalized.replacingServiceReliability(rows)
                try C53ServiceReliabilityBackupEnrollmentV1.validate(
                    records:normalized,
                    workspaceID:expectedWorkspaceID
                )
            } catch let error as BackupRestoreServiceError { throw error }
            catch { throw attributedRestoreAuthorityFailureV1(line: #line) }
        }
        if normalized.recordsSchemaVersion >= C57MyDayBackupEnrollmentV1.recordsSchemaVersion {
            do {
                let sourceWorkspaceID = WorkspaceID(rawValue:
                    identityDecision?.source.workspaceID
                        ?? normalized.myDayPlans.first?.key.workspaceID.rawValue
                        ?? legacyWorkspaceID
                )
                let targetWorkspaceID = WorkspaceID(rawValue:
                    identityDecision?.targetPointer.workspaceID
                        ?? legacyWorkspaceID
                )
                let source = try MyDayBackupSnapshotV1(
                    workspaceID: sourceWorkspaceID,
                    plans: records.myDayPlans,
                    carryoverReceipts: records.myDayCarryoverReceipts,
                    nonactivePlanReferences: records.nonactivePlanReferences
                )
                let disposition: MyDayRestoreDispositionV1
                switch identityDecision?.mode ?? .replaceExisting {
                case .emptyInstall, .replaceExisting: disposition = .replaceExact
                case .clone: disposition = .configurationCloneOmit
                case .fork: disposition = .workspaceForkNonactiveHistory
                }
                let selected = Set(source.nonactivePlanReferences)
                let retainedPlans = try source.plans.filter {
                    selected.contains(try MyDayPlanReferenceV1($0))
                }
                let targetReferences = disposition == .workspaceForkNonactiveHistory
                    ? try myDayTargetReferences(requiredBy: retainedPlans, in: normalized)
                    : []
                let prepared = try MyDayLifecycleAdapterV1.preparedRestoreSnapshot(
                    source,
                    targetWorkspaceID: targetWorkspaceID,
                    disposition: disposition,
                    operationID: partsStockOperationID,
                    targetReferences: targetReferences
                )
                normalized = normalized.replacingMyDay(prepared)
                try C57MyDayBackupEnrollmentV1.validate(normalized)
            } catch {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
        }
        if normalized.recordsSchemaVersion >= C05EvidenceMetadataBackupEnrollmentV1.recordsSchemaVersion {
            do {
                normalized = try normalized.replacingEvidenceMetadata(
                    records.evidenceAssociationEvents,
                    records.evidenceSequenceRevisions
                )
                try C05EvidenceMetadataRestoreIdentityBoundaryV1.validate(
                    normalized,
                    identity: identityDecision
                )
            } catch {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
        }
        if normalized.recordsSchemaVersion >= C04ShopReportProfileBackupEnrollmentV1.recordsSchemaVersion {
            do {
                let profiles: [ShopReportProfileV1]
                if let identityDecision {
                    profiles = try C04ShopReportProfileRestoreIdentityBoundaryV1.rebinding(
                        records.shopReportProfiles,
                        identity: identityDecision
                    )
                } else {
                    profiles = records.shopReportProfiles
                }
                normalized = normalized.replacingShopReportProfiles(profiles)
                try C04ShopReportProfileBackupEnrollmentV1.validate(normalized)
            } catch {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
        }
        if normalized.recordsSchemaVersion >= C05RoundSessionBackupEnrollmentV1.recordsSchemaVersion {
            do {
                guard roundProjection == nil || normalized.roundSessions == roundRows else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                let sessions: [RoundSessionV1]
                if let identityDecision {
                    sessions = try C05RoundSessionRestoreIdentityBoundaryV1.rebinding(
                        roundRows,
                        identity: identityDecision
                    )
                } else {
                    sessions = records.roundSessions
                }
                normalized = normalized.replacingRoundSessions(sessions)
                try C05RoundSessionBackupEnrollmentV1.validate(normalized)
            } catch {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
        }
        // Existing normalization copies predate C10. Reattach the closed,
        // immutable snapshot after those copies; clone/fork admission is
        // deliberately decided by the later C10 materialization branch.
        normalized.evidenceQuality = records.evidenceQuality
        normalized.fastSurveyInbox = records.fastSurveyInbox
        normalized.reinspectionExceptionQueue = records.reinspectionExceptionQueue
        normalized.entityIdentityResolution = records.entityIdentityResolution
        normalized.practiceWorkspaceProvenance = records.practiceWorkspaceProvenance
        normalized.lightingDayInventoryWorkflows = records.lightingDayInventoryWorkflows
        normalized.lightingNightWorkflows = records.lightingNightWorkflows
        guard let history = normalized.mutationHistory else {
            throw BackupRestoreServiceError.invalidPackage
        }
        let resetsLocalSequence: Bool
        if let identityDecision {
            let target = try workspaceIdentity(identityDecision)
            let old = try workspaceIdentity(identityDecision.oldPointer)
            resetsLocalSequence = identityDecision.mode != .replaceExisting
                || target != old
        } else {
            resetsLocalSequence = false
        }
        guard resetsLocalSequence, history.lastLocalSequence != 0 else {
            return normalized
        }
        var reset = replacingMutationHistoryForCurrentWriter(
            in: normalized,
            with: MutationHistorySnapshotV1(
                workspaceRevision: history.workspaceRevision,
                lastLocalSequence: 0,
                receipts: history.receipts,
                quarantines: history.quarantines,
                entityRevisions: history.entityRevisions
            )
        )
        reset.evidenceQuality = records.evidenceQuality
        reset.fastSurveyInbox = records.fastSurveyInbox
        reset.reinspectionExceptionQueue = records.reinspectionExceptionQueue
        reset.entityIdentityResolution = records.entityIdentityResolution
        reset.practiceWorkspaceProvenance = records.practiceWorkspaceProvenance
        reset.lightingDayInventoryWorkflows = records.lightingDayInventoryWorkflows
        reset.lightingNightWorkflows = records.lightingNightWorkflows
        return reset
        } catch {
#if DEBUG
            let diagnosticError = error as NSError
            FileHandle.standardError.write(Data(("Backup materialization failure phase=\(materializationPhase) type=\(String(reflecting: type(of: error))) domain=\(diagnosticError.domain) code=\(diagnosticError.code)\n").utf8))
#endif
            throw error
        }
    }

    func rebindingAcceptedLabelSnapshots(
        _ records: [V34BackupAcceptedLabelSnapshotRecordV1],
        identity: RestoreIdentityV1
    ) throws -> [V34BackupAcceptedLabelSnapshotRecordV1] {
        let workspaceID = WorkspaceID(rawValue: identity.targetPointer.workspaceID)
        return try records.map { record in
            let source = try record.value()
            let localActor = try LocalActorReferenceV1(
                actorReferenceID: source.recordedBy.actor.actorReferenceID,
                workspaceID: workspaceID,
                partyID: source.recordedBy.actor.partyID,
                displayName: source.recordedBy.actor.displayName
            )
            let actor = try ActorSnapshotV1(
                snapshotID: source.recordedBy.snapshotID,
                workspaceID: workspaceID,
                actor: localActor,
                responsibility: source.recordedBy.responsibility,
                displayNameAtTime: source.recordedBy.displayNameAtTime,
                capturedAt: source.recordedBy.capturedAt
            )
            let target = try WorkspaceEntityIdentityV1(
                kind: .acceptedLabelGenerationSnapshot,
                id: source.snapshotID
            )
            let expected = try WorkspaceExpectedRevisionV1(
                workspaceID: workspaceID,
                generationID: identity.targetPointer.generationID,
                writerInstanceID: identity.targetPointer.replicaID,
                workspaceRevision: source.expectedRevision.workspaceRevision,
                entityRevisions: [.init(identity: target, revision: 0)]
            )
            let rebound = try source.rebound(
                to: workspaceID,
                expectedRevision: expected,
                mutationID: try identity.destinationAcceptedLabelMutationID(for: source.mutationID),
                recordedBy: actor,
                recordedAt: source.recordedAt
            )
            guard rebound.disposition == .historicCloneOrFork else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            return try V34BackupAcceptedLabelSnapshotRecordV1(rebound)
        }.sorted { ($0.workspaceID.uuidString, $0.snapshotID.uuidString) < ($1.workspaceID.uuidString, $1.snapshotID.uuidString) }
    }

    func rebindingPlacementPoses(
        in records: V4BackupRecordsV1,
        identity: RestoreIdentityV1,
        workspaceID: WorkspaceID
    ) throws -> V4BackupRecordsV1 {
        let sourceValues = try PlacementPoseBackupRecordSetV1.decode(
            records.placementPoses
        )
        let sourceWorkspaceIDs = Set(records.placementPoses.map(\.workspaceID))
        guard sourceWorkspaceIDs.count <= 1,
              let sourceWorkspaceID = sourceWorkspaceIDs.first else {
            throw BackupRestoreServiceError.invalidPackage
        }
        guard sourceValues.poseEvents.allSatisfy({
            $0.workspaceID.rawValue == sourceWorkspaceID
        }), sourceValues.spatialAnchors.allSatisfy({
            $0.workspaceID.rawValue == sourceWorkspaceID
        }) else {
            throw BackupRestoreServiceError.invalidPackage
        }
        let needsRebind = sourceWorkspaceID != workspaceID.rawValue
            || identity.mode == .clone || identity.mode == .fork
        guard needsRebind else { return records }

        func actor(_ source: ActorSnapshotV1) throws -> ActorSnapshotV1 {
            let local = try LocalActorReferenceV1(
                actorReferenceID: source.actor.actorReferenceID,
                workspaceID: workspaceID,
                partyID: source.actor.partyID,
                displayName: source.actor.displayName
            )
            return try ActorSnapshotV1(
                snapshotID: source.snapshotID,
                workspaceID: workspaceID,
                actor: local,
                responsibility: source.responsibility,
                displayNameAtTime: source.displayNameAtTime,
                capturedAt: source.capturedAt
            )
        }

        var reboundEvents: [UUID: AssetPoseEventV1] = [:]
        for source in sourceValues.poseEvents.sorted(by: {
            ($0.revision, $0.eventID.uuidString.lowercased())
                < ($1.revision, $1.eventID.uuidString.lowercased())
        }) {
            let predecessor: AssetPoseEventV1?
            if let sourcePredecessor = source.predecessor {
                guard let value = reboundEvents[sourcePredecessor.eventID] else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                predecessor = value
            } else {
                predecessor = nil
            }
            let rebound = try source.rebound(
                to: workspaceID,
                predecessor: predecessor,
                recordedBy: actor(source.recordedBy)
            )
            guard reboundEvents.updateValue(rebound, forKey: source.eventID)
                    == nil else {
                throw BackupRestoreServiceError.invalidPackage
            }
        }

        var reboundObservations: [UUID: SpatialAnchorObservationV1] = [:]
        for source in sourceValues.spatialAnchors.sorted(by: {
            ($0.revision, $0.observationID.uuidString.lowercased())
                < ($1.revision, $1.observationID.uuidString.lowercased())
        }) {
            let predecessor: SpatialAnchorObservationV1?
            if let sourcePredecessor = source.predecessorObservationID {
                guard let value = reboundObservations[sourcePredecessor] else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                predecessor = value
            } else {
                predecessor = nil
            }
            let rebound = try source.rebound(
                to: workspaceID,
                predecessor: predecessor,
                observedBy: actor(source.observedBy)
            )
            guard reboundObservations.updateValue(rebound, forKey: source.observationID)
                    == nil else {
                throw BackupRestoreServiceError.invalidPackage
            }
        }

        let placementPoses = try (
            reboundEvents.values.map {
                V29BackupPlacementPoseRecordV1(
                    kind: .poseEvent,
                    id: $0.eventID,
                    workspaceID: workspaceID.rawValue,
                    revision: $0.revision,
                    canonicalData: try PlacementPoseCanonicalCodecV1.encode($0)
                )
            }
            + reboundObservations.values.map {
                V29BackupPlacementPoseRecordV1(
                    kind: .spatialAnchorObservation,
                    id: $0.observationID,
                    workspaceID: workspaceID.rawValue,
                    revision: $0.revision,
                    canonicalData: try PlacementPoseCanonicalCodecV1.encode($0)
                )
            }
        ).sorted {
            "\($0.kind.rawValue)\u{0}\($0.id.uuidString.lowercased())"
                < "\($1.kind.rawValue)\u{0}\($1.id.uuidString.lowercased())"
        }
        _ = try PlacementPoseBackupRecordSetV1.decode(placementPoses)
        return records.replacingPlacementPoses(placementPoses)
    }

    func recordsWithRequirementAssurance(
        _ records: V4BackupRecordsV1,
        workspaceID: UUID
    ) throws -> V4BackupRecordsV1 {
        if records.recordsSchemaVersion >= 7 { return records }
        guard records.recordsSchemaVersion <= 6,
              Set(records.requirementAssurance.map(\.workflowRecordID)).count
                == records.requirementAssurance.count,
              Set(records.requirementAssurance.map(\.workflowRecordID))
                .isSubset(of: Set(records.workflowRecords.map(\.id))) else {
            throw BackupRestoreServiceError.invalidPackage
        }
        let existing = Dictionary(uniqueKeysWithValues:
            records.requirementAssurance.map { ($0.workflowRecordID, $0) }
        )
        let assurance = try records.workflowRecords.map { record in
            if let value = existing[record.id] { return value }
            let row = try RequirementAssuranceRow.blockingUnknownBackfill(
                workflowRecordID: record.id,
                workspaceID: workspaceID,
                evaluatedRevision: 1,
                requirementID: "legacy.requirement.assurance",
                requirementVersion: 1,
                requirementTypeID: "legacy.requirement.assurance",
                policySHA256: KernelCanonicalHashV1.sha256(
                    Data("V8|LEGACY_REQUIREMENT_ASSURANCE_UNKNOWN|1".utf8)
                ),
                mutationID: record.finalizationMutationID ?? record.id,
                timestamp: record.startedAt
            )
            return try V8BackupRequirementAssuranceRecordV1(row)
        }.sorted { canonical($0.workflowRecordID) < canonical($1.workflowRecordID) }
        return V4BackupRecordsV1(
            guidedSurveys:records.guidedSurveys,
            assetLocators: records.assetLocators,
            schedules: records.schedules,
            plans: records.plans,
            placementPoses: records.placementPoses,
            accessibleDocumentAssessments:records.accessibleDocumentAssessments,
            surveyDefinitions: records.surveyDefinitions,
            fieldReferences:records.fieldReferences,
            recoverabilityReceipts:records.recoverabilityReceipts,
            clientCapabilities: records.clientCapabilities,
            privacyTransforms: records.privacyTransforms,
            measurementIntegrity: records.measurementIntegrity,
            packageEvolution: records.packageEvolution,
            fieldDrafts: records.fieldDrafts, workPackets:records.workPackets, inspectionReview: records.inspectionReview,
            evidenceAssurance: records.evidenceAssurance,
            functionalRelationships: records.functionalRelationships,
            authorityCriterion: records.authorityCriterion, assetSemantics: records.assetSemantics,
            assetCompositionEdges: records.assetCompositionEdges,
            assetCompositionEvents: records.assetCompositionEvents,
            assetPlacementEvents: records.assetPlacementEvents,
            assets: records.assets, deletionLedger: records.deletionLedger,
            evidenceFiles: records.evidenceFiles, issues: records.issues,
            locationHierarchyEvents: records.locationHierarchyEvents,
            locationMigrationReceipts: records.locationMigrationReceipts,
            locationNodes: records.locationNodes, mutationHistory: records.mutationHistory,
            packets: records.packets, partyAccountability: records.partyAccountability,
            recordsSchemaVersion: records.recordsSchemaVersion,
            reports: records.reports, requirementAssurance: assurance,
            savedSmartViews: records.savedSmartViews, sites: records.sites,
            workflowRecords: records.workflowRecords,
            lighting: records.lighting,
            lightingDayInventoryWorkflows: records.lightingDayInventoryWorkflows,
            lightingNightWorkflows: records.lightingNightWorkflows,
            assistanceAcceptanceReceipts: records.assistanceAcceptanceReceipts,
            temporalEvidence: records.temporalEvidence,
            acceptedLabelGenerationSnapshots: records.acceptedLabelGenerationSnapshots,
            operationalContacts: records.operationalContacts,
            activityContracts: records.activityContracts,
            workResources: records.workResources,
            serviceRequests: records.serviceRequests,
            serviceRequestDispositionEvents: records.serviceRequestDispositionEvents,
            serviceRequestWorkLinkEvents: records.serviceRequestWorkLinkEvents,
            serviceReliabilityIncidents: records.serviceReliabilityIncidents,
            serviceImpactSegments: records.serviceImpactSegments,
            serviceCauseAssertions: records.serviceCauseAssertions,
            serviceRemedyAssertions: records.serviceRemedyAssertions,
            serviceRepairIntervals: records.serviceRepairIntervals,
            serviceRestorationAssertions: records.serviceRestorationAssertions,
            qualifiedServiceExposures: records.qualifiedServiceExposures,
            serviceReliabilityReceipts: records.serviceReliabilityReceipts,
            partsStockSnapshot: records.partsStockSnapshot,
            myDayPlans: records.myDayPlans,
            myDayCarryoverReceipts: records.myDayCarryoverReceipts,
            nonactivePlanReferences: records.nonactivePlanReferences,
            evidenceAssociationEvents: records.evidenceAssociationEvents,
            evidenceSequenceRevisions: records.evidenceSequenceRevisions, shopReportProfiles: records.shopReportProfiles, roundSessions: records.roundSessions, importMappingProfiles: records.importMappingProfiles, bulkSessions: records.bulkSessions, bulkCommitReceipts: records.bulkCommitReceipts
        )
    }

    func rebindingLocationMigrationReceipt(
        in records: V4BackupRecordsV1,
        identity: RestoreIdentityV1,
        workspaceID: WorkspaceID,
        generationID: UUID,
        sourceAssurancePreviews: [UUID: AssuranceProjectionPreviewV1],
        members: ValidatedV4BackupMembersV1
    ) throws -> V4BackupRecordsV1 {
        guard records.locationMigrationReceipts.count <= 1 else {
            throw BackupRestoreServiceError.invalidPackage
        }
        let nodes = try records.locationNodes.map { record -> V5BackupLocationRecordV1 in
            let value = try LocationPersistenceCodecV1.decode(
                LocationNodeV1.self, from: record.canonicalData
            )
            guard value.workspaceID != workspaceID else { return record }
            let rebound = try LocationNodeV1(
                id: value.id, workspaceID: workspaceID, siteID: value.siteID,
                parentNodeID: value.parentNodeID, kind: value.kind,
                label: value.label, shortCode: value.shortCode,
                siblingOrder: value.siblingOrder, state: value.state,
                revision: value.revision,
                provenance: try LocationMutationProvenanceV1(
                    mutationID: value.provenance.mutationID,
                    occurredAt: value.provenance.occurredAt
                )
            )
            return .init(id: rebound.id, canonicalData: try LocationPersistenceCodecV1.encode(rebound))
        }
        let placements = try records.assetPlacementEvents.map { record -> V5BackupLocationRecordV1 in
            let value = try LocationPersistenceCodecV1.decode(
                AssetPlacementEventV1.self, from: record.canonicalData
            )
            guard value.workspaceID != workspaceID else { return record }
            let rebound = try AssetPlacementEventV1(
                id: value.id, workspaceID: workspaceID, assetID: value.assetID,
                siteID: value.siteID, locationNodeID: value.locationNodeID,
                predecessorEventID: value.predecessorEventID, source: value.source,
                physicalEpisodeID: value.physicalEpisodeID,
                continuity: value.continuity, pathSnapshot: value.pathSnapshot,
                mutationID: value.mutationID, occurredAt: value.occurredAt
            )
            return .init(id: rebound.id, canonicalData: try LocationPersistenceCodecV1.encode(rebound))
        }
        let reboundEdges = try records.assetCompositionEdges.map { record -> (V5BackupLocationRecordV1, AssetCompositionEdgeV1) in
            let value = try LocationPersistenceCodecV1.decode(
                AssetCompositionEdgeV1.self, from: record.canonicalData
            )
            let rebound = value.workspaceID == workspaceID ? value : try AssetCompositionEdgeV1(
                id: value.id, workspaceID: workspaceID,
                parentAssetID: value.parentAssetID, childAssetID: value.childAssetID,
                relationship: value.relationship, isActive: value.isActive,
                revision: value.revision
            )
            return (
                .init(id: rebound.id, canonicalData: try LocationPersistenceCodecV1.encode(rebound)),
                rebound
            )
        }
        let edgesByID = Dictionary(uniqueKeysWithValues: reboundEdges.map { ($0.1.id, $0.1) })
        let compositionEvents = try records.assetCompositionEvents.map { record -> V5BackupLocationRecordV1 in
            let value = try LocationPersistenceCodecV1.decode(
                AssetCompositionEventV1.self, from: record.canonicalData
            )
            guard edgesByID[value.edge.id] != nil else {
                throw BackupRestoreServiceError.invalidPackage
            }
            let eventEdge = value.edge.workspaceID == workspaceID ? value.edge : try AssetCompositionEdgeV1(
                id: value.edge.id, workspaceID: workspaceID,
                parentAssetID: value.edge.parentAssetID,
                childAssetID: value.edge.childAssetID,
                relationship: value.edge.relationship,
                isActive: value.edge.isActive,
                revision: value.edge.revision
            )
            let rebound = try AssetCompositionEventV1(
                id: value.id, workspaceID: workspaceID, edge: eventEdge,
                predecessorEventID: value.predecessorEventID, action: value.action,
                mutationID: value.mutationID, occurredAt: value.occurredAt
            )
            return .init(id: rebound.id, canonicalData: try LocationPersistenceCodecV1.encode(rebound))
        }
        func reboundNode(_ value: LocationNodeV1) throws -> LocationNodeV1 {
            guard value.workspaceID != workspaceID else { return value }
            return try LocationNodeV1(
                id: value.id, workspaceID: workspaceID, siteID: value.siteID,
                parentNodeID: value.parentNodeID, kind: value.kind,
                label: value.label, shortCode: value.shortCode,
                siblingOrder: value.siblingOrder, state: value.state,
                revision: value.revision, provenance: value.provenance
            )
        }
        let hierarchyEvents = try records.locationHierarchyEvents.map { record -> V5BackupLocationRecordV1 in
            guard let receiptData = record.secondaryCanonicalData else {
                throw BackupRestoreServiceError.invalidPackage
            }
            let sourcePlan = try LocationPersistenceCodecV1.decode(
                LocationHierarchyChangePlanV1.self, from: record.canonicalData
            )
            let sourceReceipt = try LocationPersistenceCodecV1.decode(
                LocationHierarchyChangeReceiptV1.self, from: receiptData
            )
            guard sourcePlan.operationID == record.id else {
                throw BackupRestoreServiceError.invalidPackage
            }
            guard sourcePlan.workspaceID != workspaceID else { return record }
            let expectedRevision = try WorkspaceExpectedRevisionV1(
                workspaceID: workspaceID,
                generationID: generationID,
                writerInstanceID: sourcePlan.expectedRevision.writerInstanceID,
                workspaceRevision: sourcePlan.expectedRevision.workspaceRevision,
                entityRevisions: sourcePlan.expectedRevision.entityRevisions
            )
            let destinationPlan = try LocationHierarchyChangePlanV1(
                operationID: sourcePlan.operationID,
                workspaceID: workspaceID,
                expectedRevision: expectedRevision,
                beforeNodes: try sourcePlan.beforeNodes.map(reboundNode),
                afterNodes: try sourcePlan.afterNodes.map(reboundNode),
                affectedAssetIDs: sourcePlan.affectedAssetIDs,
                assetPathChanges: sourcePlan.assetPathChanges,
                immutablePlacementReferencedNodeIDs: sourcePlan.immutablePlacementReferencedNodeIDs,
                consumerImpact: sourcePlan.consumerImpact,
                assetBindingsChange: sourcePlan.assetBindingsChange,
                operationContinuityDisposition: sourcePlan.operationContinuityDisposition,
                continuityByAssetID: sourcePlan.continuityByAssetID
            )
            let destinationReceipt = try LocationHierarchyChangeReceiptV1.importedCloneFork(
                destinationPlan: destinationPlan,
                sourcePlan: sourcePlan,
                sourceReceipt: sourceReceipt
            )
            return .init(
                id: destinationPlan.operationID,
                canonicalData: try LocationPersistenceCodecV1.encode(destinationPlan),
                secondaryCanonicalData: try LocationPersistenceCodecV1.encode(destinationReceipt)
            )
        }
        let savedSmartViews = try records.savedSmartViews.map { record -> V7BackupSavedSmartViewRecordV1 in
            let value = try record.descriptor()
            guard value.workspaceID != workspaceID.rawValue else { return record }
            return try V7BackupSavedSmartViewRecordV1(SavedSmartViewDescriptorV1(
                id: value.id,
                workspaceID: workspaceID.rawValue,
                stableID: value.stableID,
                origin: value.origin,
                builtInKind: value.builtInKind,
                name: value.name,
                query: value.query,
                scope: value.scope,
                filters: value.filters,
                sort: value.sort,
                revision: value.revision,
                mutationID: value.mutationID,
                createdAt: value.createdAt,
                updatedAt: value.updatedAt
            ))
        }
        let requirementAssurance = try records.requirementAssurance.map { record in
            let source = try record.snapshot()
            guard source.workspaceID != workspaceID.rawValue else { return record }
            let rebound = try RequirementAssuranceSnapshotV1(
                workflowRecordID: source.workflowRecordID,
                workspaceID: workspaceID.rawValue,
                evaluatedRevision: source.evaluatedRevision,
                policySetSHA256: source.policySetSHA256,
                evaluations: source.evaluations,
                findings: source.findings,
                decision: source.decision
            )
            return try V8BackupRequirementAssuranceRecordV1(
                workflowRecordID: rebound.workflowRecordID,
                canonicalData: RequirementAssuranceCanonicalV1.data(rebound),
                snapshotSHA256: rebound.snapshotSHA256,
