        sourceFunctionalRelationships: [V12BackupFunctionalRelationshipRecordV1],
        functionalRelationships: [V12BackupFunctionalRelationshipRecordV1],
        sourceReports: [V4BackupReportDTO], reboundReports: [V4BackupReportDTO],
        members: ValidatedV4BackupMembersV1,
        temporalClips: [TemporalEvidenceClipV1],
        temporalAnchors: [TimecodedEvidenceAnchorV1]
    ) throws -> [V14BackupInspectionReviewRecordV1] {
        let reboundPolicies = try Dictionary(uniqueKeysWithValues: records.compactMap { record -> (UUID, CorrectiveActionPolicyV1)? in
            guard record.kind == .correctiveActionPolicy else { return nil }
            let source = try InspectionReviewCanonicalCodecV1.decode(CorrectiveActionPolicyV1.self, from: record.canonicalData)
            let rebound = try source.rebound(to: workspaceID)
            return (rebound.releaseID, rebound)
        })
        let reboundManifests = try Dictionary(uniqueKeysWithValues: evidenceAssurance.compactMap { record -> (UUID, AssuranceManifestV1)? in
            guard record.kind == .manifest else { return nil }
            let value = try EvidenceAssuranceCanonicalCodecV1.decode(AssuranceManifestV1.self, from: record.canonicalData)
            return (value.manifestID, value)
        })
        let reboundLinks = try Dictionary(uniqueKeysWithValues: evidenceAssurance.compactMap { record -> (UUID, ClaimEvidenceLinkV1)? in
            guard record.kind == .evidenceLink else { return nil }
            let value = try EvidenceAssuranceCanonicalCodecV1.decode(ClaimEvidenceLinkV1.self, from: record.canonicalData)
            return (value.linkID, value)
        })
        var digestRebindings: [String: String] = [:]
        func normalizedReferenceID(_ id: String) -> String { UUID(uuidString:id)?.uuidString ?? id }
        func key(_ family: String, _ id: String, _ revision: UInt64, _ digest: String) -> String {
            "\(family)\u{0}\(normalizedReferenceID(id))\u{0}\(revision)\u{0}\(digest)"
        }
        func bind(_ family: String, _ id: String, _ revision: UInt64, _ old: String, _ new: String) {
            digestRebindings[key(family, id, revision, old)] = new
        }
        let reboundReportByID = Dictionary(uniqueKeysWithValues: reboundReports.map { ($0.id, $0) })
        for source in sourceReports {
            guard let rebound = reboundReportByID[source.id],
                  let bytes = members[source.snapshotRelativePath] else {
                throw BackupRestoreServiceError.invalidPackage
            }
            if source.snapshotSchemaVersion == CompletedActivitySnapshotV2.schemaVersion {
                let snapshot = try CompletedActivitySnapshotCanonicalCodecV2.decode(bytes)
                for id in [source.id.uuidString, snapshot.payload.activity.reportID,
                           snapshot.payload.activity.snapshotID,
                           snapshot.payload.activity.sourceActivityID] {
                    bind("reportSnapshot", id, UInt64(source.snapshotSchemaVersion),
                         source.snapshotSHA256, rebound.snapshotSHA256)
                    bind("completedActivitySnapshot", id, UInt64(source.snapshotSchemaVersion),
                         source.snapshotSHA256, rebound.snapshotSHA256)
                }
                continue
            }
            let snapshot = try ReportSnapshotEncoderV1().decode(bytes)
            for id in [source.id.uuidString, snapshot.reportID.uuidString,
                       snapshot.sourceRecordID.uuidString, snapshot.stableRootID.uuidString] {
                bind("reportSnapshot", id, UInt64(source.snapshotSchemaVersion), source.snapshotSHA256, rebound.snapshotSHA256)
                bind("completedActivitySnapshot", id, UInt64(source.snapshotSchemaVersion), source.snapshotSHA256, rebound.snapshotSHA256)
            }
            if let old = snapshot.functionalRelationships {
                let reboundData = try reboundReportSnapshotData(
                    bytes,
                    workspaceID: workspaceID,
                    temporalClips: temporalClips,
                    temporalAnchors: temporalAnchors
                )
                if let new = try ReportSnapshotEncoderV1().decode(reboundData).functionalRelationships {
                    bind("functionalRelationshipSnapshot", old.snapshotID.uuidString,
                         UInt64(old.schemaVersion), old.snapshotSHA256, new.snapshotSHA256)
                }
            }
        }
        let sourceLinks = try Dictionary(uniqueKeysWithValues: sourceEvidenceAssurance.compactMap { record -> (UUID, ClaimEvidenceLinkV1)? in
            guard record.kind == .evidenceLink else { return nil }
            let value = try EvidenceAssuranceCanonicalCodecV1.decode(ClaimEvidenceLinkV1.self, from: record.canonicalData)
            return (value.linkID, value)
        })
        for (id, rebound) in reboundLinks {
            guard let source = sourceLinks[id] else { throw BackupRestoreServiceError.invalidPackage }
            bind("claimEvidenceLink", id.uuidString, source.revision, source.linkSHA256, rebound.linkSHA256)
            bind("evidence", id.uuidString, source.revision, source.linkSHA256, rebound.linkSHA256)
        }
        let reboundClassifications = try Dictionary(uniqueKeysWithValues: authorityCriterion.compactMap { record -> (UUID, FindingClassificationBindingV1)? in
            guard record.kind == .findingClassificationBinding else { return nil }
            let value = try AuthorityCriterionCanonicalCodecV1.decode(FindingClassificationBindingV1.self, from: record.canonicalData)
            return (value.bindingID, value)
        })
        for record in sourceAuthorityCriterion where record.kind == .findingClassificationBinding {
            let source = try AuthorityCriterionCanonicalCodecV1.decode(FindingClassificationBindingV1.self, from: record.canonicalData)
            guard let rebound = reboundClassifications[source.bindingID] else { throw BackupRestoreServiceError.invalidPackage }
            bind("finding", source.findingID.uuidString, source.revision, source.bindingSHA256, rebound.bindingSHA256)
            bind("criterion", source.criterionID, source.revision, source.bindingSHA256, rebound.bindingSHA256)
        }
        let reboundRelationshipEvents = try Dictionary(uniqueKeysWithValues: functionalRelationships.compactMap { record -> (UUID, AssetFunctionalRelationshipEventV1)? in
            guard record.kind == .event else { return nil }
            let value = try FunctionalRelationshipCanonicalCodecV1.decode(AssetFunctionalRelationshipEventV1.self, from: record.canonicalData)
            return (value.eventID, value)
        })
        for record in sourceFunctionalRelationships where record.kind == .event {
            let source = try FunctionalRelationshipCanonicalCodecV1.decode(AssetFunctionalRelationshipEventV1.self, from: record.canonicalData)
            guard let rebound = reboundRelationshipEvents[source.eventID] else { throw BackupRestoreServiceError.invalidPackage }
            for id in [source.relationshipID.uuidString, source.eventID.uuidString] {
                bind("functionalRelationship", id, source.revision, source.eventSHA256, rebound.eventSHA256)
            }
        }
        func reboundDigest(_ family: String, _ id: String, _ revision: UInt64, _ digest: String) -> String {
            digestRebindings[key(family, id, revision, digest)] ?? digest
        }
        func reboundItem(_ value: ChangeRequestItemReferenceV1) throws -> ChangeRequestItemReferenceV1 {
            let family: String
            switch value.kind { case .review: family="review";case .finding:family="finding";case .criterion:family="criterion";case .evidence:family="evidence";case .functionalRelationship:family="functionalRelationship" }
            return try .init(kind:value.kind,itemID:value.itemID,itemRevision:value.itemRevision,
                             itemSHA256:reboundDigest(family,value.itemID,value.itemRevision,value.itemSHA256))
        }
        func reboundSubject(_ value: InspectionReviewSubjectReferenceV1) throws -> InspectionReviewSubjectReferenceV1 {
            let family: String
            switch value.kind { case .completedActivitySnapshot:family="completedActivitySnapshot";case .reportSnapshot:family="reportSnapshot";case .finding:family="finding" }
            return try .init(workspaceID:workspaceID,kind:value.kind,subjectID:value.subjectID,
                             subjectRevision:value.subjectRevision,
                             subjectSHA256:reboundDigest(family,value.subjectID,value.subjectRevision,value.subjectSHA256),
                             packageRelease:value.packageRelease)
        }
        let reboundTransitions = try Dictionary(uniqueKeysWithValues: records.compactMap { record -> (UUID, InspectionReviewTransitionV1)? in
            guard record.kind == .reviewTransition else { return nil }
            let source = try InspectionReviewCanonicalCodecV1.decode(InspectionReviewTransitionV1.self, from: record.canonicalData)
            let base = try source.rebound(to: workspaceID)
            let rebound = try InspectionReviewTransitionV1(
                transitionID:base.transitionID,reviewID:base.reviewID,workspaceID:workspaceID,
                subject:reboundSubject(source.subject),fromState:base.fromState,toState:base.toState,
                actor:base.actor,reason:base.reason,dispositionID:base.dispositionID,
                changeRequestIDs:base.changeRequestIDs,successorReviewID:base.successorReviewID,
                successorSubject:try source.successorSubject.map(reboundSubject),occurredAt:base.occurredAt,
                recordedAt:base.recordedAt,predecessorTransitionID:base.predecessorTransitionID,
                revision:base.revision,mutationID:base.mutationID)
            bind("review", source.reviewID.uuidString, source.revision, source.transitionSHA256, rebound.transitionSHA256)
            return (source.transitionID, rebound)
        })
        func reboundEvidence(_ values: [ReviewEvidenceReferenceV1]) throws -> [ReviewEvidenceReferenceV1] {
            try values.map { value in
                let family: String
                switch value.kind {case .claimEvidenceLink:family="claimEvidenceLink";case .verifiedRecheck:family="verifiedRecheck";case .completedActivitySnapshot:family="completedActivitySnapshot";case .requirementEvaluation:family="requirementEvaluation";case .functionalRelationshipSnapshot:family="functionalRelationshipSnapshot";case .externalEvidenceReference:family="externalEvidenceReference"}
                return try ReviewEvidenceReferenceV1(
                    kind: value.kind, referenceID: value.referenceID,
                    revision: value.revision,
                    sha256: reboundDigest(family,value.referenceID,value.revision,value.sha256)
                )
            }
        }
        return try records.map { record in
            let data: Data
            let identity: (UUID, UInt64)
            switch record.kind {
            case .reviewTransition:
                let source = try InspectionReviewCanonicalCodecV1.decode(InspectionReviewTransitionV1.self, from: record.canonicalData)
                guard let rebound = reboundTransitions[source.transitionID] else { throw BackupRestoreServiceError.invalidPackage }
                data = try InspectionReviewCanonicalCodecV1.encode(rebound); identity = (rebound.transitionID, rebound.revision)
            case .reviewDisposition:
                let source = try InspectionReviewCanonicalCodecV1.decode(ReviewDispositionV1.self, from: record.canonicalData)
                let base = try source.rebound(to: workspaceID)
                let manifest = try base.assuranceManifestID.map { id -> AssuranceManifestV1 in
                    guard let value = reboundManifests[id] else { throw BackupRestoreServiceError.invalidPackage }
                    return value
                }
                let rebound = try ReviewDispositionV1(
                    dispositionID: base.dispositionID, reviewID: base.reviewID,
                    workspaceID: workspaceID, subject: reboundSubject(source.subject),
                    reviewRevision: base.reviewRevision, kind: base.kind,
                    reviewer: base.reviewer, reason: base.reason,
                    changeRequestIDs: base.changeRequestIDs,
                    assuranceManifestID: manifest?.manifestID,
                    assuranceManifestRevision: manifest?.revision,
                    assuranceManifestSHA256: manifest?.manifestSHA256,
                    recordedAt: base.recordedAt,
                    supersedesDispositionID: base.supersedesDispositionID,
                    revision: base.revision, mutationID: base.mutationID
                )
                data = try InspectionReviewCanonicalCodecV1.encode(rebound); identity = (rebound.dispositionID, rebound.revision)
            case .changeRequest:
                let source = try InspectionReviewCanonicalCodecV1.decode(ChangeRequestV1.self, from: record.canonicalData)
                let base = try source.rebound(to: workspaceID)
                let resolution = try base.resolution.map { value in
                    try ChangeRequestResolutionV1(
                        kind: value.kind, resolver: value.resolver,
                        evidence: reboundEvidence(value.evidence), reason: value.reason,
                        resolvedAt: value.resolvedAt
                    )
                }
                let rebound = try ChangeRequestV1(
                    requestRevisionID: base.requestRevisionID, requestID: base.requestID,
                    reviewID: base.reviewID, workspaceID: workspaceID,
                    reviewRevision: base.reviewRevision, item: reboundItem(source.item), reason: base.reason,
                    requirements: base.requirements, requester: base.requester, state: base.state,
                    resolution: resolution, recordedAt: base.recordedAt,
                    supersedesRequestRevisionID: base.supersedesRequestRevisionID,
                    revision: base.revision, mutationID: base.mutationID
                )
                data = try InspectionReviewCanonicalCodecV1.encode(rebound); identity = (rebound.requestRevisionID, rebound.revision)
            case .correctiveActionPolicy:
                let source = try InspectionReviewCanonicalCodecV1.decode(CorrectiveActionPolicyV1.self, from: record.canonicalData)
                let rebound = try source.rebound(to: workspaceID)
                data = try InspectionReviewCanonicalCodecV1.encode(rebound); identity = (rebound.releaseID, rebound.revision)
            case .correctiveActionEvent:
                let source = try InspectionReviewCanonicalCodecV1.decode(CorrectiveActionEventV1.self, from: record.canonicalData)
                let base = try source.rebound(to: workspaceID)
                guard let policy = reboundPolicies[base.policy.releaseID] else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                let rebound = try CorrectiveActionEventV1(
                    eventID: base.eventID, actionID: base.actionID, workspaceID: workspaceID,
                    source: reboundItem(source.source), policy: CorrectiveActionPolicyReferenceV1(policy),
                    priority: base.priority, state: base.state, assignee: base.assignee,
                    recorder: base.recorder, due: base.due,
                    closureEvidence: reboundEvidence(base.closureEvidence),
                    verifier: base.verifier, reopenTrigger: base.reopenTrigger, reason: base.reason,
                    occurredAt: base.occurredAt, recordedAt: base.recordedAt,
                    predecessorEventID: base.predecessorEventID, revision: base.revision,
                    mutationID: base.mutationID
                )
                data = try InspectionReviewCanonicalCodecV1.encode(rebound); identity = (rebound.eventID, rebound.revision)
            }
            guard identity == (record.id, record.revision) else {
                throw BackupRestoreServiceError.invalidPackage
            }
            return .init(kind: record.kind, id: identity.0, workspaceID: workspaceID.rawValue,
                         revision: identity.1, canonicalData: data)
        }
    }

    func rebindingEvidenceAssurance(
        _ records: [V13BackupEvidenceAssuranceRecordV1], workspaceID: WorkspaceID,
        sourcePreviews: [UUID: AssuranceProjectionPreviewV1]
    ) throws -> [V13BackupEvidenceAssuranceRecordV1] {
        do {
            var visibilities: [UUID: EvidenceVisibilityV1] = [:]
            for record in records where record.kind == .visibility {
                let source = try EvidenceAssuranceCanonicalCodecV1.decode(EvidenceVisibilityV1.self, from: record.canonicalData)
                visibilities[source.visibilityID] = source.workspaceID == workspaceID ? source : try source.rebound(to: workspaceID)
            }
            var links: [UUID: ClaimEvidenceLinkV1] = [:]
            for record in records where record.kind == .evidenceLink {
                let source = try EvidenceAssuranceCanonicalCodecV1.decode(ClaimEvidenceLinkV1.self, from: record.canonicalData)
                guard let visibility = visibilities[source.visibilityID] else { throw BackupRestoreServiceError.invalidPackage }
                links[source.linkID] = source.workspaceID == workspaceID ? source : try source.rebound(to: workspaceID, visibility: visibility)
            }
            var manifests: [UUID: AssuranceManifestV1] = [:]
            for record in records where record.kind == .manifest {
                let source = try EvidenceAssuranceCanonicalCodecV1.decode(AssuranceManifestV1.self, from: record.canonicalData)
                if source.workspaceID == workspaceID { manifests[source.manifestID] = source; continue }
                let sourceLinks = source.includedLinks + source.excludedLinks
                let reboundLinks = try sourceLinks.map { link -> ClaimEvidenceLinkV1 in
                    guard let value = links[link.linkID] else { throw BackupRestoreServiceError.invalidPackage }
                    return value
                }
                guard let frozenPreview = sourcePreviews[source.sourcePreviewID] else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                try source.validateFresh(preview: frozenPreview)
                let preview = try frozenPreview.rebound(to: workspaceID, links: reboundLinks)
                manifests[source.manifestID] = try source.rebound(to: workspaceID, preview: preview)
            }
            var attestations: [UUID: AttestationV1] = [:]
            for record in records where record.kind == .attestation {
                let source = try EvidenceAssuranceCanonicalCodecV1.decode(AttestationV1.self, from: record.canonicalData)
                guard let manifest = manifests[source.manifestID] else { throw BackupRestoreServiceError.invalidPackage }
                attestations[source.attestationID] = source.workspaceID == workspaceID ? source : try source.rebound(to: workspaceID, manifest: manifest)
            }
            return try records.map { record in
                let valueData: Data
                switch record.kind {
                case .visibility: valueData = try EvidenceAssuranceCanonicalCodecV1.encode(visibilities[record.id]!)
                case .evidenceLink: valueData = try EvidenceAssuranceCanonicalCodecV1.encode(links[record.id]!)
                case .manifest: valueData = try EvidenceAssuranceCanonicalCodecV1.encode(manifests[record.id]!)
                case .attestation: valueData = try EvidenceAssuranceCanonicalCodecV1.encode(attestations[record.id]!)
                }
                return .init(kind: record.kind, id: record.id, workspaceID: workspaceID.rawValue,
                             revision: record.revision, canonicalData: valueData)
            }
        } catch { throw BackupRestoreServiceError.invalidPackage }
    }

    func recordsWithObservationAndTime(
        _ records: V4BackupRecordsV1
    ) throws -> V4BackupRecordsV1 {
        guard records.recordsSchemaVersion < 4 else { return records }
        let workflowRecords = try records.workflowRecords.map { value in
            let data = try observationAndTimeData(
                for: value,
                recordsSchemaVersion: records.recordsSchemaVersion
            )
            return value.replacingObservationAndTime(
                basisData: data.basis,
                temporalData: data.temporal
            )
        }
        return V4BackupRecordsV1(
            guidedSurveys:[],
            placementPoses: [],
            accessibleDocumentAssessments:[],
            surveyDefinitions: [],
            fieldReferences: [],
            evidenceAssurance: [], functionalRelationships: [], authorityCriterion: [], assetSemantics: [],
            assetCompositionEdges: records.assetCompositionEdges,
            assetCompositionEvents: records.assetCompositionEvents,
            assetPlacementEvents: records.assetPlacementEvents,
            assets: records.assets,
            deletionLedger: records.deletionLedger,
            evidenceFiles: records.evidenceFiles,
            issues: records.issues,
            locationHierarchyEvents: records.locationHierarchyEvents,
            locationMigrationReceipts: records.locationMigrationReceipts,
            locationNodes: records.locationNodes,
            mutationHistory: records.mutationHistory,
            packets: records.packets,
            partyAccountability: [],
            recordsSchemaVersion: 4,
            reports: records.reports,
            requirementAssurance: records.requirementAssurance,
            savedSmartViews: records.savedSmartViews,
            sites: records.sites,
            workflowRecords: workflowRecords,
            lightingDayInventoryWorkflows: records.lightingDayInventoryWorkflows,
            lightingNightWorkflows: records.lightingNightWorkflows,
            activityContracts: records.activityContracts,
            workResources: records.workResources,
            serviceRequests: records.serviceRequests,
            serviceRequestDispositionEvents: records.serviceRequestDispositionEvents,
            serviceRequestWorkLinkEvents: records.serviceRequestWorkLinkEvents,
            serviceReliabilityIncidents: records.serviceReliabilityIncidents,
            serviceImpactSegments: records.serviceImpactSegments,
            serviceCauseAssertions: records.serviceCauseAssertions,
            serviceRemedyAssertions: records.serviceRemedyAssertions,
            serviceRepairIntervals: records.serviceRepairIntervals,
            serviceRestorationAssertions: records.serviceRestorationAssertions,
            qualifiedServiceExposures: records.qualifiedServiceExposures,
            serviceReliabilityReceipts: records.serviceReliabilityReceipts,
            partsStockSnapshot: records.partsStockSnapshot,
            myDayPlans: records.myDayPlans,
            myDayCarryoverReceipts: records.myDayCarryoverReceipts,
            nonactivePlanReferences: records.nonactivePlanReferences,
            evidenceAssociationEvents: records.evidenceAssociationEvents,
            evidenceSequenceRevisions: records.evidenceSequenceRevisions, shopReportProfiles: records.shopReportProfiles, roundSessions: records.roundSessions, importMappingProfiles: records.importMappingProfiles, bulkSessions: records.bulkSessions, bulkCommitReceipts: records.bulkCommitReceipts
        )
    }

    func entityIdentityResolutionCommands(
        from history: MutationHistorySnapshotV1,
        snapshot: EntityIdentityResolutionBackupSnapshotV1
    ) throws -> [MutationIDV1: EntityIdentityResolutionMutationCommandV1] {
        var commands: [MutationIDV1: EntityIdentityResolutionMutationCommandV1] = [:]
        var genericReceipts: [MutationIDV1: MutationReceiptV1] = [:]
        for record in history.receipts {
            let envelope = try MutationEnvelopeV1.decodeCanonical(from: record.envelopeData)
            guard case let .applyEntityIdentityResolution(command) = envelope.command else {
                continue
            }
            let generic = try MutationReceiptV1.decodeCanonical(from: record.receiptData)
            try command.validate()
            guard commands.updateValue(command, forKey: command.mutationID) == nil,
                  genericReceipts.updateValue(generic, forKey: command.mutationID) == nil,
                  generic.mutationID == command.mutationID,
                  generic.identity.workspaceID == command.workspaceID,
                  generic.expectedRevision.generationID == command.expectedRevision.generationID,
                  generic.expectedRevision.workspaceRevision
                    == command.expectedRevision.workspaceRevision,
                  generic.commandBodySHA256 == (try WorkspaceMutationCanonicalV1.sha256(
                      WorkspaceCommandV1.applyEntityIdentityResolution(command)
                  )),
                  generic.postImages.map(\.semanticSHA256).sorted()
                    == command.payload.semanticSHA256s.sorted() else {
                throw BackupRestoreServiceError.invalidPackage
            }
        }
        let expected = Set(snapshot.mutationReceipts.map(\.mutationID))
        guard Set(commands.keys) == expected, Set(genericReceipts.keys) == expected else {
            throw BackupRestoreServiceError.invalidPackage
        }
        for typed in snapshot.mutationReceipts {
            guard let command = commands[typed.mutationID],
                  let generic = genericReceipts[typed.mutationID] else {
                throw BackupRestoreServiceError.invalidPackage
            }
            try typed.validate(command: command)
            guard typed.recoveryState == .receiptCommitted,
                  typed.generationID == generic.expectedRevision.generationID,
                  typed.priorWorkspaceRevision == generic.expectedRevision.workspaceRevision,
                  typed.resultingWorkspaceRevision == generic.resultingRevision.workspaceRevision,
                  typed.semanticSHA256s == generic.postImages.map(\.semanticSHA256).sorted() else {
                throw BackupRestoreServiceError.invalidPackage
            }
        }
        return commands
    }

    func materialize(
        _ value: ValidatedV4BackupPackageV1,
        records: V4BackupRecordsV1,
        generationID: UUID,
        identityDecision: RestoreIdentityV1?,
        legacyDestinationIdentity: WorkspaceReplicaIdentityV1,
        partsStockOperationID: UUID,
        partsStockCompletedAt: Date,
        photoPlans: [CheckRunnerPhotoBackupRestorePlanV1] = [],
        cloneFinalMedia: [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember] = [:],
        retainedCanonicalMembers: RetainedCanonicalRestoreMembersV1? = nil,
        retainedCanonicalAuthorityCheck: () throws -> Void = {}
    ) throws {
#if DEBUG
        var restoreStagingPhase = "validate-records"
        var restoreStagingPhaseStartedAt = DispatchTime.now().uptimeNanoseconds
        func beginRestoreStagingPhase(_ phase: String) {
            restoreStagingPhase = phase
            restoreStagingPhaseStartedAt = DispatchTime.now().uptimeNanoseconds
        }
#endif
        do {
            if records.recordsSchemaVersion
                >= C47ActivityContractPersistenceBoundaryV2.recordsSchemaVersion {
                // The original archive is the only side allowed through the
                // live resolved-reference validator. Rebound target bytes are
                // instead re-proved canonically here after the private restore
                // mapping check has bound source and target truth.
                try validateResolvedActivityContracts(
                    in: value.records,
                    members: value.members
                )
                _ = try records.validateC47ActivityContracts()
            }
#if DEBUG
            beginRestoreStagingPhase("create-staging")
#endif
            try generationFactory.createRestoreStagingGeneration(
                id: generationID,
                authority: generationAuthority,
                recordsSchemaVersion: records.recordsSchemaVersion,
                sourceGenerationID: value.manifest.source.sourceGenerationID,
                archiveProvenanceSHA256: try BackupCanonicalEncoderV1()
                    .encodeManifest(value.manifest).sha256
            ) { context in
                if records.recordsSchemaVersion >= C55PartsStockBackupEnrollmentV1.recordsSchemaVersion {
                    let targetWorkspaceID = WorkspaceID(rawValue:
                        identityDecision?.targetPointer.workspaceID
                            ?? legacyDestinationIdentity.workspaceID.rawValue
                    )
                    let disposition = C55PartsStockRestoreIdentityBoundaryV1.disposition(
                        for: identityDecision?.mode ?? .replaceExisting
                    )
                    guard let sourceSnapshot = value.records.partsStockSnapshot,
                          let materializedSnapshot = records.partsStockSnapshot else {
                        throw BackupRestoreServiceError.invalidPackage
                    }
#if DEBUG
                    beginRestoreStagingPhase("c55-materialize")
#endif
                    let receipt = try PartsStockLifecycleAdapterV1(modelContext: context)
                        .materializeRestoreStaging(
                            sourceSnapshot,
                            materializedSnapshot: disposition == .replace
                                && sourceSnapshot.workspaceID != targetWorkspaceID
                                ? materializedSnapshot : nil,
                            targetWorkspaceID: targetWorkspaceID,
                            operationID: partsStockOperationID,
                            disposition: disposition,
                            completedAt: partsStockCompletedAt
                        )
                    try receipt.validate()
                    guard receipt.operationID == partsStockOperationID,
                          receipt.sourceWorkspaceID == sourceSnapshot.workspaceID,
                          receipt.targetWorkspaceID == targetWorkspaceID,
                          receipt.disposition == disposition,
                          receipt.snapshotSHA256 == sourceSnapshot.snapshotSHA256,
                          receipt.effectSHA256 == materializedSnapshot.snapshotSHA256 else {
                        throw attributedRestoreAuthorityFailureV1(line: #line)
                    }
                } else if records.partsStockSnapshot != nil {
                    throw BackupRestoreServiceError.invalidPackage
                }
#if DEBUG
                beginRestoreStagingPhase("insert-records")
#endif
                try insert(
                    records,
                    into: context,
                    generationID: generationID,
                    identityDecision: identityDecision,
                    legacyDestinationIdentity: legacyDestinationIdentity
                )
#if DEBUG
                beginRestoreStagingPhase("factory-save")
#endif
            }
#if DEBUG
            beginRestoreStagingPhase("write-members")
#endif
            try writeMembers(
                value,
                records: records,
                to: generationFactory.restoreStagingGenerationURL(
                    id: generationID
                ),
                generationID: generationID,
                photoPlans: photoPlans,
                cloneFinalMedia: cloneFinalMedia,
                retainedCanonicalMembers: retainedCanonicalMembers,
                retainedCanonicalAuthorityCheck: retainedCanonicalAuthorityCheck
            )
#if DEBUG
            beginRestoreStagingPhase("protect-tree")
#endif
            try protectGenerationTree(
                id: generationID,
                root: generationFactory.restoreStagingGenerationURL(id: generationID),
                staging: true
            )
        } catch {
            let originalError = error
#if DEBUG
            let diagnosticError = originalError as NSError
            let restoreStagingPhaseElapsedMilliseconds =
                (DispatchTime.now().uptimeNanoseconds - restoreStagingPhaseStartedAt) / 1_000_000
            FileHandle.standardError.write(Data((
                "BackupRestoreService.materialize failure"
                    + " phase=\(restoreStagingPhase)"
                    + " elapsedMillis=\(restoreStagingPhaseElapsedMilliseconds)"
                    + " type=\(String(reflecting: type(of: originalError)))"
                    + " domain=\(diagnosticError.domain)"
                    + " code=\(diagnosticError.code)\n"
            ).utf8))
#endif
            let cleanupError: Error?
            do {
                try generationFactory.removeRestoreStagingGeneration(
                    id: generationID,
                    authority: generationAuthority
                )
                cleanupError = nil
            } catch {
                cleanupError = error
            }
            if let failure = cleanupError as? ProtectedFilePolicyError,
               failure == .protectedDataUnavailable {
                throw failure
            }
            if let failure = originalError as? ProtectedFilePolicyError,
               failure == .protectedDataUnavailable {
                throw failure
            }
            throw BackupRestoreServiceError.materializationFailed
        }
    }

    private func photoGenerationMembers(_ plans: [CheckRunnerPhotoBackupRestorePlanV1]) throws
        -> [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember] {
        var result: [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember] = [:]
        for plan in plans {
            for member in plan.generationMembers {
                if let previous = result[member.relativePath], previous != member {
                    throw BackupRestoreServiceError.invalidPackage
                }
                result[member.relativePath] = member
            }
        }
        return result
    }

    private func photoOwnsEvidence(_ evidence: V4BackupEvidenceFileDTO,
        members: [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember]) throws -> Bool {
        let original = members[evidence.relativePath]
        let thumbnail = members[evidence.thumbnailRelativePath]
        guard original != nil || thumbnail != nil else { return false }
        guard let original, let thumbnail,
              original.kind == .original, thumbnail.kind == .thumbnail,
              original.entry.byteCount == evidence.byteCount, original.entry.sha256 == evidence.sha256,
              thumbnail.entry.byteCount == evidence.thumbnailByteCount,
              thumbnail.entry.sha256 == evidence.thumbnailSHA256 else {
            throw BackupRestoreServiceError.invalidPackage
        }
        return true
    }

    private struct PhotoRestorePreparation {
        let composition: CheckRunnerPhotoRestoreCompositionPlanV1
        let records: V4BackupRecordsV1
        let core: CheckRunnerPhotoRestoreBindingCoreV1
        let sources: [CheckRunnerPhotoRestoreMemberSourceV1]
        let currentRecords: V4BackupRecordsV1
        let retainedCanonicalMembers: RetainedCanonicalRestoreMembersV1?

        var plans: [CheckRunnerPhotoBackupRestorePlanV1] { composition.photoRestorePlans }
        var childStageIDs: Set<UUID> { Set(plans.flatMap { $0.children.map(\.stageID) }) }
        var proof: StoreRestoreGenerationManifestProofV1 { get throws { try core.manifestProof(plans: plans) } }
    }

    private func configurationCloneFinalMedia(package: ValidatedV4BackupPackageV1,
        records: V4BackupRecordsV1) throws
        -> [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember] {
        guard records.fieldDrafts.isEmpty else { throw BackupRestoreServiceError.invalidPackage }
        var entries: [String: V4BackupEntryV1] = [:]
        for entry in package.manifest.entries {
            guard entries.updateValue(entry, forKey: entry.path) == nil else {
                throw BackupRestoreServiceError.invalidPackage
            }
        }
        var result: [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember] = [:]
        func include(_ sourcePath: String, targetPath: String, count: Int64, sha256: String,
            mime: String, kind: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember.Kind) throws {
            guard let entry = entries[sourcePath], entry.path == sourcePath,
                  entry.mimeType == mime, Int64(entry.byteCount) == count,
                  entry.sha256 == sha256 else { throw BackupRestoreServiceError.invalidPackage }
            let member = CheckRunnerPhotoBackupRestorePlanV1.GenerationMember(
                entry: entry, relativePath: targetPath, kind: kind)
            if let existing = result[targetPath] {
                guard existing == member else { throw BackupRestoreServiceError.invalidPackage }
            } else { result[targetPath] = member }
        }
        for evidence in records.evidenceFiles {
            let id = canonical(evidence.id)
            guard evidence.relativePath == "evidence/\(id)/original.jpg",
                  evidence.thumbnailRelativePath == "evidence/\(id)/thumbnail.jpg" else {
                throw BackupRestoreServiceError.invalidPackage
            }
            try include("media/\(id).jpg", targetPath: evidence.relativePath,
                count: Int64(evidence.byteCount), sha256: evidence.sha256,
                mime: "image/jpeg", kind: .original)
            try include("thumbnails/\(id).jpg", targetPath: evidence.thumbnailRelativePath,
                count: Int64(evidence.thumbnailByteCount), sha256: evidence.thumbnailSHA256,
                mime: "image/jpeg", kind: .thumbnail)
        }
        let temporal = try decodedTemporalEvidenceRows(records)
        _ = try package.records.validateC33TemporalEvidence()
        let destinationWorkspaceID = temporal.clips.first?.workspaceID ?? temporal.anchors.first?.workspaceID
        if let destinationWorkspaceID {
            guard try rebindingTemporalEvidence(package.records.temporalEvidence,
                guidedSurveys: records.guidedSurveys, workspaceID: destinationWorkspaceID) == records.temporalEvidence else {
                throw BackupRestoreServiceError.invalidPackage
            }
        } else if !package.records.temporalEvidence.isEmpty { throw BackupRestoreServiceError.invalidPackage }
        for clip in temporal.clips {
            guard let sourceWorkspaceID = package.manifest.source.workspaceID,
                  let digest = clip.original.digests.digest(for: .sha256)?.hexadecimalValue else {
                throw BackupRestoreServiceError.invalidPackage
            }
            let path = "content/\(sourceWorkspaceID.uuidString.lowercased())/\(clip.original.contentID)/original.bin"
            try include(path, targetPath: TemporalEvidenceBackupMemberV1.original(for: clip),
                count: clip.original.byteLength, sha256: digest, mime: clip.original.mediaType, kind: .original)
        }
        return result
    }

    private func prepareConfigurationCloneStagingProof(currentRecords: V4BackupRecordsV1,
        workspaceID: WorkspaceID) throws -> ConfigurationCloneEmptyStagingProofV1 {
        // An absent root alone does not prove an empty canonical stage family.
        guard try canonicalStageItems(currentRecords).isEmpty else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        return try prepareEmptyConfigurationCloneStagingProof(workspaceID: workspaceID)
    }

    private func prepareEmptyConfigurationCloneStagingProof(workspaceID: WorkspaceID) throws
        -> ConfigurationCloneEmptyStagingProofV1 {
        let observation = try DraftAttachmentStagingAdapterV1.observePhotoBackupRoot(
            applicationSupportURL: applicationSupportURL, workspaceID: workspaceID)
        switch observation {
        case .existing(let owner): return .existing(try owner.prepareEmptyPhotoBackupVerification())
        case .absent(let absent): return .absent(try absent.preparePhotoBackupVerification(
            canonicalStages: [], childStageIDs: [:]))
        }
    }

    private func cloneRetirementOwner(_ binding: ConfigurationCloneRetirementBindingV1) throws
        -> DraftAttachmentStagingAdapterV1 {
        let observation = try DraftAttachmentStagingAdapterV1.observePhotoBackupRoot(
            applicationSupportURL: applicationSupportURL, workspaceID: binding.core.plan.workspaceID)
        guard case .existing(let owner) = observation else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        return owner
    }

    private func reopenCloneRetirement(_ binding: ConfigurationCloneRetirementBindingV1) throws
        -> DraftConfigurationCloneRetirementPreparedV1 {
        guard let ownership = binding.ownership else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        let prepared = try cloneRetirementOwner(binding).reopenConfigurationCloneRetirement(
            authority: .init(core: binding.core, applicationSupportURL: applicationSupportURL), ownership: ownership)
#if DEBUG
        prepared.observationForTesting = configurationCloneRetirementObservationForTesting
        prepared.beforeClaimForTesting = configurationCloneRetirementBeforeClaimForTesting
#endif
        return prepared
    }

    private func verifyCloneRetirementBeforeClaim(_ binding: ConfigurationCloneRetirementBindingV1) throws {
        guard binding.ownership == nil else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        try cloneRetirementOwner(binding).verifyConfigurationCloneRetirementPlan(
            authority: .init(core: binding.core, applicationSupportURL: applicationSupportURL))
    }

    private func cloneRetirementPermit(_ binding: ConfigurationCloneRetirementBindingV1,
        disposition: DraftConfigurationCloneRetirementPermitV1.Disposition) throws
        -> DraftConfigurationCloneRetirementPermitV1 {
        try .init(binding: binding, applicationSupportURL: applicationSupportURL, disposition: disposition)
    }

    private func requireCloneRetirementDestination(_ binding: ConfigurationCloneRetirementBindingV1,
        session: StoreGenerationSession) throws -> V4BackupRecordsV1 {
        let intent = try binding.core.boundIntent()
        guard let identity = intent.identity, !session.modelContext.hasChanges,
              session.generationID == intent.newGenerationID,
              session.workspaceID.rawValue == identity.targetPointer.workspaceID else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let values = try records(in: session.modelContext)
        guard values.fieldDrafts.isEmpty,
              try BackupCanonicalEncoderV1().encodeRecords(values).sha256 == binding.core.destinationRecordsSHA256 else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        try validateRows(session.modelContext, expected: values)
        return values
    }

    /// Only canonical/history and generation media are read here. The adapter
    /// separately proves public/private placement using the saved inode claims.
    private func requireCloneRetirementIncumbent(_ binding: ConfigurationCloneRetirementBindingV1) throws
        -> (session: StoreGenerationSession, records: V4BackupRecordsV1, plan: CheckRunnerPhotoBackupRestorePlanV1) {
        let intent = try binding.core.boundIntent()
        guard let identity = intent.identity else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        let old = try generationFactory.openInstalledGeneration(id: intent.oldGenerationID,
            identity: workspaceIdentity(identity.oldPointer), authority: generationAuthority)
        guard !old.modelContext.hasChanges else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        let values = try records(in: old.modelContext)
        let plan = try binding.core.resolveCurrent(in: values)
        try validateUnpublishedTargetSession(old, expected: values, staging: false, photoPlans: [plan])
        return (old, values, plan)
    }

    private func prepareLiveCloneRetirement(_ initial: ConfigurationCloneRetirementBindingV1,
        clone: ConfigurationClonePreparation,
        validateCurrent: @MainActor () async throws -> Void,
        validateCurrentLocked: () throws -> Void) async throws -> ConfigurationCloneRetirementBindingV1 {
        guard initial.ownership == nil, initial.completion == .active,
              clone.retirementPlan == initial.core.plan,
              let owner = clone.physical.owner, case .existing(let proof) = clone.physical.staging else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let registry = try generationFactory.makeGenerationLeaseRegistry(ownerID: initial.core.plan.restoreID)
        try registry.withNoMigrationReservation {
            try validateCurrentLocked()
            try initial.core.requireIntent(requiredPhotoRestoreIntent())
            guard try cloneRetirementBinding(restoreID: initial.core.plan.restoreID) == initial else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try proof.withVerificationLock {}
        }
        let prepared = try await owner.prepareConfigurationCloneRetirement(
            authority: .init(core: initial.core, applicationSupportURL: applicationSupportURL),
            currentVerification: proof)
        try await validateCurrent()
#if DEBUG
        try configurationCloneRetirementObservationForTesting?("after-retirement-scaffold")
#endif
        let owned = try ConfigurationCloneRetirementBindingV1(core: initial.core, ownership: prepared.ownership)
        try registry.withNoMigrationReservation {
            try validateCurrentLocked()
            try initial.core.requireIntent(requiredPhotoRestoreIntent())
            try persistCloneRetirementBindingLocked(owned, replacing: initial)
#if DEBUG
            try configurationCloneRetirementObservationForTesting?("after-retirement-ownership")
#endif
        }
        return owned
    }

    /// The generation factory already holds G. Quarantine and its final proof
    /// retain R through the exact factory CAS; no metadata method acquires G.
    private func publishCloneRetirement(_ binding: ConfigurationCloneRetirementBindingV1,
        expectedIntent: RestoreIntentV1, currentMedia: CheckRunnerPhotoMediaBackupPreparedVerificationV1,
        validateCurrentLocked: () throws -> Void,
        publishingPointer: () throws -> Void) throws {
        try validateCurrentLocked()
        try binding.core.requireIntent(expectedIntent)
        guard binding.completion == .active, binding.ownership != nil,
              try intentStore.load() == expectedIntent,
              try cloneRetirementBinding(restoreID: expectedIntent.restoreID) == binding,
              try generationFactory.currentGenerationID(authority: generationAuthority) == expectedIntent.oldGenerationID,
              try !generationAuthority.retiredGenerationIDs().contains(expectedIntent.oldGenerationID) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        try requireCurrentPointerBinding(expectedIntent, currentID: expectedIntent.oldGenerationID)
        try currentMedia.withVerificationLock {
            try reopenCloneRetirement(binding).quarantine(
                permit: cloneRetirementPermit(binding, disposition: .quarantine), publishingPointer: {
                    try publishingPointer()
#if DEBUG
                    try self.configurationCloneRetirementObservationForTesting?("after-retirement-pointer")
#endif
                })
        }
    }

    /// Terminal checks also work with a retained value after the sidecar has
    /// been removed. No absent file grants a new cleanup capability.
    private func validateConfigurationCloneRetirementBoundary(_ retained: ConfigurationCloneRetirementBindingV1,
        session: StoreGenerationSession?, expectedIntent: RestoreIntentV1?, retireIntent: Bool) throws {
        let original = try retained.core.boundIntent()
        // Opening an accepted generation acquires its reader lease under G.
        // Acquire those sessions before entering the publication/cleanup lock.
        let incumbent = try requireCloneRetirementIncumbent(retained)
        let observedCurrentID = try generationFactory.currentGenerationID(authority: generationAuthority)
        let destination: StoreGenerationSession?
        if observedCurrentID == original.newGenerationID, let identity = original.identity {
            destination = try session ?? generationFactory.openInstalledGeneration(id: original.newGenerationID,
                identity: workspaceIdentity(identity.targetPointer), authority: generationAuthority)
        } else { destination = nil }
        let destinationRecords = try destination.map { try requireCloneRetirementDestination(retained, session: $0) }
        let registry = try generationFactory.makeGenerationLeaseRegistry(ownerID: original.restoreID)
        try registry.withNoMigrationReservation {
            try Task.checkCancellation()
            let currentID = try generationFactory.currentGenerationID(authority: generationAuthority)
            guard currentID == observedCurrentID, !incumbent.session.modelContext.hasChanges,
                  try records(in: incumbent.session.modelContext) == incumbent.records else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try requireCurrentPointerBinding(original, currentID: currentID)
            guard try intentStore.load() == expectedIntent else { throw BackupRestoreServiceError.invalidRestoreAuthority }
            if let expectedIntent { try retained.core.requireIntent(expectedIntent) }
            let saved = try cloneRetirementBinding(restoreID: original.restoreID)
            if let saved {
                guard saved.core == retained.core, saved.ownership == retained.ownership else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
            } else if expectedIntent != nil { throw BackupRestoreServiceError.invalidRestoreAuthority }
            let binding = saved ?? retained
            try validateUnpublishedTargetSession(incumbent.session, expected: incumbent.records,
                staging: false, photoPlans: [incumbent.plan])
            let disposition: DraftConfigurationCloneRetirementPermitV1.Disposition
            let terminal: ConfigurationCloneRetirementBindingV1.Completion
            if currentID == original.newGenerationID {
                guard let destination, let values = destinationRecords,
                      try generationAuthority.retiredGenerationIDs().contains(original.oldGenerationID),
                      expectedIntent == nil || expectedIntent?.phase == .newGenerationValidated else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
                guard !destination.modelContext.hasChanges,
                      try records(in: destination.modelContext) == values else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
                try validateUnpublishedTargetSession(destination, expected: values, staging: false)
                guard binding.completion != .rolledBack else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                disposition = .retire; terminal = .retired
                if binding.completion == .active, saved != nil {
                    guard binding.ownership != nil else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                    try reopenCloneRetirement(binding).finish(permit: cloneRetirementPermit(binding, disposition: .retire))
                }
            } else {
                guard currentID == original.oldGenerationID, session == nil,
                      binding.completion == .rolledBack,
                      try !generationAuthority.retiredGenerationIDs().contains(original.oldGenerationID) else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
                disposition = .rollback; terminal = .rolledBack
            }
            let completed = try ConfigurationCloneRetirementBindingV1(core: binding.core,
                ownership: binding.ownership, completion: terminal)
            @MainActor func completeMetadata() throws {
                if let saved {
                    try persistCloneRetirementBindingLocked(completed, replacing: saved)
#if DEBUG
                    try configurationCloneRetirementObservationForTesting?("after-retirement-terminal-binding")
#endif
                    if retireIntent {
                        if let expectedIntent { try intentStore.remove(expected: expectedIntent) }
#if DEBUG
                        try configurationCloneRetirementObservationForTesting?("after-retirement-intent-removal")
#endif
                        try removeCloneRetirementBindingLocked(completed)
#if DEBUG
                        try configurationCloneRetirementObservationForTesting?("after-retirement-sidecar-removal")
#endif
                        try cleanupEmptyRestoreDirectories()
                    }
                } else {
                    guard expectedIntent == nil else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                }
            }
            if binding.ownership != nil {
                try reopenCloneRetirement(completed).withTerminalVerificationLock(
                    permit: cloneRetirementPermit(completed, disposition: disposition), completeMetadata)
            } else {
                guard disposition == .rollback else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                try verifyCloneRetirementBeforeClaim(completed)
                try completeMetadata()
                try verifyCloneRetirementBeforeClaim(completed)
            }
        }
    }

    /// Called before legacy empty-clone admission or generic abandoned cleanup.
    /// Old-pointer recovery restores the complete before image first, then the
    /// incumbent generation state machine can discard its target safely.
    private func prepareColdConfigurationCloneRetirement(
        retained: ConfigurationCloneRetirementBindingV1? = nil) throws -> ConfigurationCloneRetirementBindingV1? {
        let actualIntent = try intentStore.load()
        guard var binding = try pendingCloneRetirementBindingAtStartup(intent: actualIntent) else {
            guard actualIntent?.cloneRetirementPlanSHA256 == nil else { throw BackupRestoreServiceError.invalidRestoreAuthority }
            if retained != nil, actualIntent != nil { throw BackupRestoreServiceError.invalidRestoreAuthority }
            return retained
        }
        if let retained {
            guard binding.core == retained.core,
                  binding.ownership == retained.ownership || binding.isImmediateSuccessor(of: retained) else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
        }
        try ensureGenerationAuthority()
        guard try pendingPhotoBindingAtStartup(intent: actualIntent) == nil else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let original = try binding.core.boundIntent()
        guard let identity = original.identity else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        let currentID = try generationFactory.currentGenerationID(authority: generationAuthority)
        try requireCurrentPointerBinding(original, currentID: currentID)
        let retired = try generationAuthority.retiredGenerationIDs()
        guard !retired.contains(original.newGenerationID),
              currentID == original.newGenerationID || !retired.contains(original.oldGenerationID) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        if let actualIntent { try binding.core.requireIntent(actualIntent) }
        else {
            guard binding.completion != .active || (binding.ownership == nil && currentID == original.oldGenerationID) else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
        }
        let incumbent = try requireCloneRetirementIncumbent(binding)
        let presence = try generationFactory.generationPresence(id: original.newGenerationID, authority: generationAuthority)
        guard !(presence.staging && presence.installed),
              currentID != original.newGenerationID || (presence.installed && !presence.staging),
              presence.staging || presence.installed || binding.completion == .rolledBack else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        var installedNames = Set(retired.map(canonical))
        installedNames.insert(canonical(original.oldGenerationID))
        if presence.installed { installedNames.insert(canonical(original.newGenerationID)) }
        guard Set(try generationAuthority.installedGenerationNames()) == installedNames,
              Set(try generationAuthority.restoreGenerationNames()) == (presence.staging ? [canonical(original.newGenerationID)] : []) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        let destination: StoreGenerationSession?
        if presence.staging {
            destination = try generationFactory.openRestoreStagingGeneration(id: original.newGenerationID,
                identity: workspaceIdentity(identity.targetPointer), authority: generationAuthority)
        } else if presence.installed {
            destination = try generationFactory.openInstalledGeneration(id: original.newGenerationID,
                identity: workspaceIdentity(identity.targetPointer), authority: generationAuthority)
        } else { destination = nil }
        let destinationRecords = try destination.map { try requireCloneRetirementDestination(binding, session: $0) }
        if let destination, let values = destinationRecords {
            guard validRecoveredRecords(intent: original, old: incumbent.records, target: values) else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try validateUnpublishedTargetSession(destination, expected: values, staging: presence.staging)
            if currentID == original.newGenerationID {
                try generationFactory.requireInstalledRestoreGenerationSnapshot(expectedOldID: original.oldGenerationID,
                    generationID: original.newGenerationID,
                    expectedManifestDigest: identity.targetPointer.generationManifestSHA256,
                    authority: generationAuthority)
            }
        }
        let importNames = try generationAuthority.importStagingNames()
        guard importNames.count <= 1 else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        if let name = importNames.first {
            guard currentID == original.oldGenerationID else { throw BackupRestoreServiceError.invalidRestoreAuthority }
            let url = applicationSupportURL.appendingPathComponent("FieldEvidenceRestore/staging", isDirectory: true)
                .appendingPathComponent(name, isDirectory: true)
            let package = try BackupPackageValidatorV1(route: packageValidationRoute()).validate(stagedPackageURL: url)
            guard try BackupCanonicalEncoderV1().encodeManifest(package.manifest).sha256 == binding.core.sourceManifestSHA256 else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
        }
        let registry = try generationFactory.makeGenerationLeaseRegistry(ownerID: original.restoreID)
        try registry.withNoMigrationReservation {
            guard try intentStore.load() == actualIntent,
                  try cloneRetirementBinding(restoreID: original.restoreID) == binding,
                  try generationFactory.currentGenerationID(authority: generationAuthority) == currentID,
                  try generationAuthority.retiredGenerationIDs() == retired,
                  !incumbent.session.modelContext.hasChanges,
                  try records(in: incumbent.session.modelContext) == incumbent.records else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try requireCurrentPointerBinding(original, currentID: currentID)
            try validateUnpublishedTargetSession(incumbent.session, expected: incumbent.records,
                staging: false, photoPlans: [incumbent.plan])
            if let destination, let values = destinationRecords {
                guard !destination.modelContext.hasChanges, try records(in: destination.modelContext) == values else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
                try validateUnpublishedTargetSession(destination, expected: values, staging: presence.staging)
            }
            if currentID == original.oldGenerationID {
                guard binding.completion != .retired,
                      actualIntent == nil || actualIntent?.phase == .prepared || actualIntent?.phase == .generationInstalled else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
                if binding.ownership != nil {
                    if binding.completion == .active {
                        try reopenCloneRetirement(binding).rollback(permit: cloneRetirementPermit(binding, disposition: .rollback))
                    }
                    let completed = try ConfigurationCloneRetirementBindingV1(core: binding.core,
                        ownership: binding.ownership, completion: .rolledBack)
                    try reopenCloneRetirement(completed).withTerminalVerificationLock(
                        permit: cloneRetirementPermit(completed, disposition: .rollback)) {
                            try persistCloneRetirementBindingLocked(completed, replacing: binding)
#if DEBUG
                            try configurationCloneRetirementObservationForTesting?("after-retirement-rollback-binding")
#endif
                        }
                    binding = completed
                } else {
                    // A private preparation without its ownership receipt is
                    // deliberately unclaimed. Exact-before verification rejects
                    // it and keeps both bytes and recovery metadata intact.
                    try verifyCloneRetirementBeforeClaim(binding)
                    let completed = try ConfigurationCloneRetirementBindingV1(core: binding.core, completion: .rolledBack)
                    try persistCloneRetirementBindingLocked(completed, replacing: binding)
#if DEBUG
                    try configurationCloneRetirementObservationForTesting?("after-retirement-rollback-binding")
#endif
                    try verifyCloneRetirementBeforeClaim(completed)
                    binding = completed
                }
            } else {
                guard currentID == original.newGenerationID, binding.ownership != nil,
                      binding.completion != .rolledBack else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                if binding.completion == .retired {
                    guard retired.contains(original.oldGenerationID) else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                    try reopenCloneRetirement(binding).withTerminalVerificationLock(
                        permit: cloneRetirementPermit(binding, disposition: .retire)) {}
                } else if !retired.contains(original.oldGenerationID) {
                    try reopenCloneRetirement(binding).withQuarantinedVerificationLock(
                        permit: cloneRetirementPermit(binding, disposition: .quarantine)) {}
                } else {
                    // The validated intent plus durable retired set grants only
                    // resumed owned-subset cleanup. Finish performs that proof.
                    guard actualIntent?.phase == .newGenerationValidated else {
                        throw BackupRestoreServiceError.invalidRestoreAuthority
                    }
                }
            }
        }
        return binding
    }

    private func prepareColdConfigurationCloneGuard(retained: ConfigurationCloneEmptyStagingGuardV1? = nil)
        throws -> ConfigurationCloneEmptyStagingGuardV1? {
        guard let intent = try intentStore.load(), let identity = intent.identity,
              identity.mode == .clone else { return nil }
        guard RestoreIntentCodecV1.valid(intent) else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        if intent.cloneRetirementPlanSHA256 != nil {
            guard let binding = try pendingCloneRetirementBindingAtStartup(intent: intent) else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try binding.core.requireIntent(intent)
            return nil
        }
        guard try pendingCloneRetirementBindingAtStartup(intent: intent) == nil else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        try ensureGenerationAuthority()
        let currentID = try generationFactory.currentGenerationID(authority: generationAuthority)
        try requireCurrentPointerBinding(intent, currentID: currentID)
        if let retained {
            try retained.requireIntent(intent)
            let registry = try generationFactory.makeGenerationLeaseRegistry(ownerID: intent.restoreID)
            try registry.withNoMigrationReservation {
                guard try intentStore.load() == intent,
                      try generationFactory.currentGenerationID(authority: generationAuthority) == currentID else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
                try requireCurrentPointerBinding(intent, currentID: currentID)
                try retained.proof.withVerificationLock {}
            }
            return retained
        }
        // Reject a changed physical namespace before opening any old store.
        let proof = try prepareEmptyConfigurationCloneStagingProof(
            workspaceID: WorkspaceID(rawValue: identity.oldPointer.workspaceID))
        let old = try generationFactory.openInstalledGeneration(id: intent.oldGenerationID,
            identity: workspaceIdentity(identity.oldPointer), authority: generationAuthority)
        let oldRecords = try records(in: old.modelContext)
        guard try canonicalStageItems(oldRecords).isEmpty else { throw BackupRestoreServiceError.invalidRestoreAuthority }
        let guardValue = try ConfigurationCloneEmptyStagingGuardV1(intent: intent, proof: proof)
        let registry = try generationFactory.makeGenerationLeaseRegistry(ownerID: intent.restoreID)
        try registry.withNoMigrationReservation {
            guard try intentStore.load() == intent,
                  try generationFactory.currentGenerationID(authority: generationAuthority) == currentID,
                  !old.modelContext.hasChanges, try records(in: old.modelContext) == oldRecords else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try requireCurrentPointerBinding(intent, currentID: currentID)
            try proof.withVerificationLock {}
        }
        return guardValue
    }

    private func validateConfigurationCloneBoundary(_ guardValue: ConfigurationCloneEmptyStagingGuardV1,
        session: StoreGenerationSession?, expectedRecords: V4BackupRecordsV1?,
        expectedIntent: RestoreIntentV1?, retireIntent: Bool = false) throws {
        let registry = try generationFactory.makeGenerationLeaseRegistry(ownerID: guardValue.restoreID)
        try registry.withNoMigrationReservation {
            try Task.checkCancellation()
            if let expectedIntent { try guardValue.requireIntent(expectedIntent) }
            let currentID = session?.generationID ?? guardValue.identity.oldPointer.generationID
            guard try intentStore.load() == expectedIntent,
                  try generationFactory.currentGenerationID(authority: generationAuthority) == currentID else {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            // The retained intent binds the exact original pointer facts even
            // after the durable cleanup intent has been retired.
            try requireCurrentPointerBinding(guardValue.originalIntent, currentID: currentID)
            if let session {
                guard currentID == guardValue.identity.targetPointer.generationID,
                      session.workspaceID.rawValue == guardValue.identity.targetPointer.workspaceID,
                      !session.modelContext.hasChanges, let expectedRecords,
                      try records(in: session.modelContext) == expectedRecords,
                      expectedRecords.fieldDrafts.isEmpty else {
                    throw BackupRestoreServiceError.invalidRestoreAuthority
                }
            } else if expectedRecords != nil || expectedIntent != nil {
                throw BackupRestoreServiceError.invalidRestoreAuthority
            }
            try guardValue.proof.withVerificationLock {
                if retireIntent {
                    guard session != nil, let expectedIntent,
                          expectedIntent.phase == .newGenerationValidated,
                          try photoPublicationBinding(restoreID: expectedIntent.restoreID) == nil,
                          !fileManager.fileExists(atPath: draftPublicationBindingURL(
                            restoreID: expectedIntent.restoreID).path) else {
                        throw BackupRestoreServiceError.invalidRestoreAuthority
                    }
                    // Clone has no draft publication binding. Retire only its
                    // exact intent while G and the original empty-root R proof
                    // remain held; neither operation below acquires G.
                    try intentStore.remove(expected: expectedIntent)
                    try cleanupEmptyRestoreDirectories()
                    guard try intentStore.load() == nil else { throw BackupRestoreServiceError.invalidRestoreAuthority }
                }
            }
        }
    }

    private func materializeConfigurationCloneFinalMedia(
        _ members: [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember],
        package: ValidatedV4BackupPackageV1, generationID: UUID,
        validateCurrent: @MainActor () async throws -> Void) async throws {
        let root = generationFactory.restoreStagingGenerationURL(id: generationID)
        let authority = ConfigurationCloneFinalMediaGenerationAuthorityV1(generationID: generationID,
            rootURL: root, rootIdentity: try ReportPDFAnchoredFile.rootIdentity(at: root),
            members: members.keys.sorted().compactMap { members[$0] }, memberSource: .package(package.members),
            maximumMemberByteCount: package.members.maximumMemberByteCount)
        try await EvidenceBundleStore(cloneFinalMediaGeneration: authority).restoreConfigurationCloneFinalMediaGeneration()
#if DEBUG
        try await configurationCloneObservationForTesting?(.afterFinalMediaCopy)
#endif
        try await validateCurrent()
        try Task.checkCancellation()
    }

    private func hasPhotoCheckpoints(_ records: V4BackupRecordsV1) throws -> Bool {
        let release = try CheckRunnerPhotoDraftCodecV1.release()
        for row in records.fieldDrafts where row.kind == .checkpoint {
            let checkpoint = try FieldDraftCanonicalCodecV1.decode(FieldDraftCheckpointV1.self, from: row.canonicalData)
            if checkpoint.codec == release { return true }
        }
        return false
    }

