                for value in values.restorationAssertions { context.insert(try ServiceRestorationAssertionRow(value)) }
                for value in values.qualifiedExposures { context.insert(try QualifiedServiceExposureRow(value)) }
            } catch let error as BackupRestoreServiceError {
                throw error
            } catch {
                throw attributedRestorePackageFailureV1(line: #line)
            }
        } else if !records.serviceReliabilityIncidents.isEmpty
                    || !records.serviceImpactSegments.isEmpty
                    || !records.serviceCauseAssertions.isEmpty
                    || !records.serviceRemedyAssertions.isEmpty
                    || !records.serviceRepairIntervals.isEmpty
                    || !records.serviceRestorationAssertions.isEmpty
                    || !records.qualifiedServiceExposures.isEmpty
                    || !records.serviceReliabilityReceipts.isEmpty {
            throw attributedRestorePackageFailureV1(line: #line)
        }
        if let mutationHistory = records.mutationHistory {
            guard records.recordsSchemaVersion == 3
                    || records.recordsSchemaVersion == 4
                    || records.recordsSchemaVersion == 5
                    || records.recordsSchemaVersion == 6
                    || records.recordsSchemaVersion == 7
                    || records.recordsSchemaVersion == 8
                    || records.recordsSchemaVersion == 9
                    || records.recordsSchemaVersion == 10
                    || records.recordsSchemaVersion == 11
                    || records.recordsSchemaVersion == 12
                    || records.recordsSchemaVersion == 13
                    || records.recordsSchemaVersion == 14
                    || records.recordsSchemaVersion == 15
                    || records.recordsSchemaVersion == 16
                    || records.recordsSchemaVersion == 17
                    || records.recordsSchemaVersion == 18
                    || records.recordsSchemaVersion == 19
                    || records.recordsSchemaVersion == 20
                    || records.recordsSchemaVersion == 21
                    || records.recordsSchemaVersion == 22
                    || records.recordsSchemaVersion == 23
                    || records.recordsSchemaVersion == 24
                    || records.recordsSchemaVersion == 25
                    || records.recordsSchemaVersion == 26
                    || records.recordsSchemaVersion == 27
                    || records.recordsSchemaVersion == 28
                    || records.recordsSchemaVersion == 29
                    || records.recordsSchemaVersion == 30
                    || records.recordsSchemaVersion == 31
                    || records.recordsSchemaVersion == 32
                    || records.recordsSchemaVersion == 33
                    || records.recordsSchemaVersion == 34
                    || records.recordsSchemaVersion == C47ActivityContractPersistenceBoundaryV2.recordsSchemaVersion
                    || records.recordsSchemaVersion == C49BackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == 37
                    || records.recordsSchemaVersion == C52ServiceRequestReplaceRestoreBoundaryV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == C53ServiceReliabilityBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == C55PartsStockBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == C57MyDayBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == C04ShopReportProfileBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == C05RoundSessionBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == C08ImportBulkBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == ReinspectionExceptionQueueBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == EntityIdentityResolutionBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == LightingDayInventoryBackupEnrollmentV1.recordsSchemaVersion
                    || records.recordsSchemaVersion == LightingNightWorkflowBackupEnrollmentV1.recordsSchemaVersion else {
                throw attributedRestorePackageFailureV1(line: #line)
            }
            do {
                let identity = try identityDecision.map {
                    try workspaceIdentity($0)
                } ?? legacyDestinationIdentity
                let journal = try MutationJournalStoreV1(
                    modelContext: context,
                    identity: identity,
                    generationID: generationID
                )
                let disposition: MutationHistoryRestoreIdentityV1
                if identityDecision == nil
                    || (identityDecision?.mode == .replaceExisting
                        && identityDecision?.targetPointer.workspaceID
                            == identityDecision?.oldPointer.workspaceID
                        && identityDecision?.targetPointer.replicaID
                            == identityDecision?.oldPointer.replicaID) {
                    disposition = .preserve
                } else if records.recordsSchemaVersion
                            >= C55PartsStockBackupEnrollmentV1.recordsSchemaVersion,
                          let identityDecision,
                          identityDecision.mode == .emptyInstall
                            || identityDecision.mode == .replaceExisting {
                    disposition = .destinationPreservingPartsStock(
                        identity,
                        generationID: generationID
                    )
                } else {
                    disposition = .destination(
                        identity,
                        generationID: generationID
                    )
                }
                try journal.replaceHistory(
                    with: mutationHistory,
                    identityDisposition: disposition
                )
            } catch {
                throw attributedRestorePackageFailureV1(line: #line)
            }
        }
    }

    func writeMembers(
        _ value: ValidatedV4BackupPackageV1,
        records: V4BackupRecordsV1,
        to root: URL,
        generationID: UUID,
        photoPlans: [CheckRunnerPhotoBackupRestorePlanV1] = [],
        cloneFinalMedia: [String: CheckRunnerPhotoBackupRestorePlanV1.GenerationMember] = [:],
        retainedCanonicalMembers: RetainedCanonicalRestoreMembersV1? = nil,
        retainedCanonicalAuthorityCheck: () throws -> Void = {}
    ) throws {
        var consumedRetainedPaths = Set<String>()
        func canonicalMember(_ path: String) throws -> Data? {
            if value.members.keys.contains(path) {
                guard retainedCanonicalMembers?.keys.contains(path) != true else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                return value.members[path]
            }
            guard let bytes = try retainedCanonicalMembers?.bytes(path,
                authorityCheck: retainedCanonicalAuthorityCheck) else { return nil }
            guard consumedRetainedPaths.insert(path).inserted else {
                throw BackupRestoreServiceError.invalidPackage
            }
            return bytes
        }
        try retainedCanonicalMembers?.validateObservations(authorityCheck: retainedCanonicalAuthorityCheck)
        var photoMembers = try photoGenerationMembers(photoPlans)
        if !cloneFinalMedia.isEmpty {
            guard photoPlans.isEmpty,
                  try cloneFinalMedia == configurationCloneFinalMedia(package: value, records: records) else {
                throw BackupRestoreServiceError.invalidPackage
            }
            photoMembers = cloneFinalMedia
        }
        for evidence in records.evidenceFiles {
            if try photoOwnsEvidence(evidence, members: photoMembers) { continue }
            let id = canonical(evidence.id)
            try protectStagingDirectory(
                root: root,
                relativePath: "evidence/\(id)",
                generationID: generationID
            )
            try writeExact(
                try canonicalMember("media/\(id).jpg"),
                to: root.appendingPathComponent(evidence.relativePath),
                expectedHash: evidence.sha256,
                generationID: generationID
            )
            try writeExact(
                try canonicalMember("thumbnails/\(id).jpg"),
                to: root.appendingPathComponent(evidence.thumbnailRelativePath),
                expectedHash: evidence.thumbnailSHA256,
                generationID: generationID
            )
        }
        let temporal = try decodedTemporalEvidenceRows(records)
        _ = try value.records.validateC33TemporalEvidence()
        let destinationWorkspaceID = temporal.clips.first?.workspaceID
            ?? temporal.anchors.first?.workspaceID
        if let destinationWorkspaceID {
            let expectedRecords = try rebindingTemporalEvidence(
                value.records.temporalEvidence,
                guidedSurveys: records.guidedSurveys,
                workspaceID: destinationWorkspaceID
            )
            guard expectedRecords == records.temporalEvidence else {
                throw BackupRestoreServiceError.invalidPackage
            }
        } else if !value.records.temporalEvidence.isEmpty {
            throw BackupRestoreServiceError.invalidPackage
        }
        if !temporal.clips.isEmpty, value.manifest.source.workspaceID == nil {
            throw BackupRestoreServiceError.invalidPackage
        }
        var restoredTemporalOriginalPaths = Set<String>()
        for clip in temporal.clips {
            guard let sourceWorkspaceID = value.manifest.source.workspaceID else {
                throw BackupRestoreServiceError.invalidPackage
            }
            guard let digest = clip.original.digests.digest(for: .sha256)?.hexadecimalValue else {
                throw BackupRestoreServiceError.invalidPackage
            }
            let sourcePath = "content/\(sourceWorkspaceID.uuidString.lowercased())/\(clip.original.contentID)/original.bin"
            let targetPath = try TemporalEvidenceBackupMemberV1.original(for: clip)
            if let owned = photoMembers[targetPath] {
                guard owned.entry.sha256 == digest,
                      Int64(owned.entry.byteCount) == clip.original.byteLength,
                      owned.kind == .original else { throw BackupRestoreServiceError.invalidPackage }
                continue
            }
            guard let bytes = value.members[sourcePath], Int64(bytes.count) == clip.original.byteLength else {
                throw BackupRestoreServiceError.invalidPackage
            }
            if restoredTemporalOriginalPaths.insert(targetPath).inserted {
                try protectStagingDirectory(
                    root: root,
                    relativePath: "content/\(clip.workspaceID.rawValue.uuidString.lowercased())/\(clip.original.contentID)",
                    generationID: generationID
                )
                try writeExact(
                    bytes,
                    to: root.appendingPathComponent(targetPath),
                    expectedHash: digest,
                    generationID: generationID
                )
            }
        }
        if records.recordsSchemaVersion >= C05EvidenceMetadataBackupEnrollmentV1.recordsSchemaVersion {
            var contentKeys = Set<String>()
            for event in records.evidenceAssociationEvents {
                for contentID in [event.contentID, event.previousContentID].compactMap({ $0 }) {
                    contentKeys.insert("\(event.workspaceID)|\(contentID)")
                }
            }
            for key in contentKeys.sorted() {
                let components = key.split(separator: "|", maxSplits: 1).map(String.init)
                guard components.count == 2 else { throw BackupRestoreServiceError.invalidPackage }
                let directory = "content/\(components[0])/\(components[1])"
                let markerPath = "\(directory)/derivative-publication.json"
                guard let markerData = value.members[markerPath] else { continue }
                let marker = try EvidenceCurationCanonicalCodecV1.decode(
                    EvidenceDerivativePublicationMarkerV1.self, from: markerData
                )
                try marker.validate()
                guard marker.workspaceID.rawValue.uuidString.lowercased() == components[0],
                      marker.result.derivative.contentID == components[1],
                      let digest = marker.result.derivative.digests.digest(for: .sha256) else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                try protectStagingDirectory(root: root, relativePath: directory, generationID: generationID)
                if let owned = photoMembers["\(directory)/original.bin"] {
                    guard owned.entry.sha256 == digest.hexadecimalValue,
                          Int64(owned.entry.byteCount) == marker.result.derivative.byteLength,
                          owned.kind == .original else { throw BackupRestoreServiceError.invalidPackage }
                } else {
                    try writeExact(value.members["\(directory)/original.bin"],
                        to: root.appendingPathComponent("\(directory)/original.bin"),
                        expectedHash: digest.hexadecimalValue, generationID: generationID)
                }
                try writeExact(markerData, to: root.appendingPathComponent(markerPath),
                    expectedHash: CanonicalJSONV1.sha256(markerData), generationID: generationID)
            }
        }
        if !records.reports.isEmpty {
            try protectStagingDirectory(
                root: root,
                relativePath: "snapshots",
                generationID: generationID
            )
        }
        if records.reports.contains(where: { $0.pdfState == "ready" }) {
            try protectStagingDirectory(
                root: root,
                relativePath: "pdfs",
                generationID: generationID
            )
        }
        for report in records.reports {
            var snapshotData = try canonicalMember(report.snapshotRelativePath)
            if let source = snapshotData,
               CanonicalJSONV1.sha256(source) != report.snapshotSHA256 {
                guard let workspaceID = temporal.clips.first?.workspaceID
                    ?? records.evidenceAssurance.first.map({ WorkspaceID(rawValue: $0.workspaceID) }) else {
                    throw BackupRestoreServiceError.invalidPackage
                }
                snapshotData = try reboundReportSnapshotData(
                    source,
                    workspaceID: workspaceID,
                    temporalClips: temporal.clips,
                    temporalAnchors: temporal.anchors
                )
            }
            try writeExact(
                snapshotData,
                to: root.appendingPathComponent(report.snapshotRelativePath),
                expectedHash: report.snapshotSHA256,
                generationID: generationID
            )
            if let path = report.pdfRelativePath,
               let hash = report.pdfSHA256 {
                try writeExact(
                    try canonicalMember(path),
                    to: root.appendingPathComponent(path),
                    expectedHash: hash,
                    generationID: generationID
                )
            }
        }
        guard consumedRetainedPaths == (retainedCanonicalMembers?.keys ?? []) else {
            throw BackupRestoreServiceError.invalidRestoreAuthority
        }
        try retainedCanonicalMembers?.validateObservations(authorityCheck: retainedCanonicalAuthorityCheck)
    }

    func writeExact(
        _ data: Data?,
        to url: URL,
        expectedHash: String,
        generationID: UUID
    ) throws {
        guard let data,
              CanonicalJSONV1.sha256(data) == expectedHash else {
            throw BackupRestoreServiceError.invalidPackage
        }
        let root = generationFactory.restoreStagingGenerationURL(id: generationID)
        let relative = try relativePath(of: url, within: root)
        let components = try validatedPathComponents(relative)
        guard let finalName = components.last else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        let parentRelative = components.dropLast().joined(separator: "/")
        let temporaryName = ".\(finalName).restore-next"
        let temporaryRelative = parentRelative.isEmpty
            ? temporaryName
            : "\(parentRelative)/\(temporaryName)"
        let authorityCheck = {
            try self.generationAuthority.requireStagingGeneration(id: generationID)
        }

        try withPinnedDirectory(
            root: root,
            relativePath: parentRelative,
            createMissing: false,
            authorityCheck: authorityCheck
        ) { parentDescriptor, verifyDirectories in
            guard try itemExists(parent: parentDescriptor, name: finalName) == false,
                  try itemExists(parent: parentDescriptor, name: temporaryName) == false else {
                throw BackupRestoreServiceError.materializationFailed
            }
            let descriptor = Darwin.openat(
                parentDescriptor,
                temporaryName,
                O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW,
                mode_t(0o600)
            )
            guard descriptor >= 0 else {
                throw BackupRestoreServiceError.materializationFailed
            }
            defer { _ = Darwin.close(descriptor) }
            var temporaryIdentity: PinnedIdentity?
            do {
                try data.withUnsafeBytes { raw in
                    guard let base = raw.baseAddress else { return }
                    var offset = 0
                    while offset < raw.count {
                        let count = Darwin.write(
                            descriptor,
                            base.advanced(by: offset),
                            raw.count - offset
                        )
                        if count > 0 {
                            offset += count
                        } else if errno != EINTR {
                            throw BackupRestoreServiceError.materializationFailed
                        }
                    }
                }
                guard Darwin.fsync(descriptor) == 0 else {
                    throw BackupRestoreServiceError.materializationFailed
                }
                var information = stat()
                guard Darwin.fstat(descriptor, &information) == 0,
                      (information.st_mode & S_IFMT) == S_IFREG,
                      information.st_nlink == 1 else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
                let identity = PinnedIdentity(information)
                temporaryIdentity = identity
                try verifyDirectories()
                guard try itemIdentity(
                    parent: parentDescriptor,
                    name: temporaryName
                ) == identity else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
                try withoutActuallyEscaping(verifyDirectories) { verifyDirectories in
                    _ = try ProtectedFilePolicyV1.applyAndVerify(
                        .stagingFile,
                        relativePath: temporaryRelative,
                        within: root,
                        authorityCheck: {
                            try verifyDirectories()
                            guard try self.itemIdentity(
                                parent: parentDescriptor,
                                name: temporaryName
                            ) == identity else {
                                throw attributedRestoreAuthorityFailureV1(line: #line)
                            }
                        }
                    )
                }
                guard try itemIdentity(
                    parent: parentDescriptor,
                    name: temporaryName
                ) == identity,
                      try itemExists(parent: parentDescriptor, name: finalName) == false else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
                guard Darwin.renameatx_np(
                    parentDescriptor,
                    temporaryName,
                    parentDescriptor,
                    finalName,
                    UInt32(RENAME_EXCL)
                ) == 0,
                      Darwin.fsync(parentDescriptor) == 0 else {
                    throw BackupRestoreServiceError.materializationFailed
                }
                try withoutActuallyEscaping(verifyDirectories) { verifyDirectories in
                    _ = try ProtectedFilePolicyV1.applyAndVerify(
                        .stagingFile,
                        relativePath: relative,
                        within: root,
                        authorityCheck: {
                            try verifyDirectories()
                            guard try self.itemIdentity(
                                parent: parentDescriptor,
                                name: finalName
                            ) == identity else {
                                throw attributedRestoreAuthorityFailureV1(line: #line)
                            }
                        }
                    )
                }
                guard try itemIdentity(
                    parent: parentDescriptor,
                    name: finalName
                ) == identity,
                      try readRegularFile(
                          parent: parentDescriptor,
                          name: finalName,
                          expected: identity
                      ) == data else {
                    throw BackupRestoreServiceError.materializationFailed
                }
            } catch {
                if let temporaryIdentity,
                   let currentIdentity = try? itemIdentity(
                       parent: parentDescriptor,
                       name: temporaryName
                   ),
                   currentIdentity == temporaryIdentity {
                    _ = Darwin.unlinkat(parentDescriptor, temporaryName, 0)
                    _ = Darwin.fsync(parentDescriptor)
                }
                throw error
            }
        }
    }

    func protectStagingDirectory(
        root: URL,
        relativePath: String,
        generationID: UUID
    ) throws {
        let authorityCheck = {
            try self.generationAuthority.requireStagingGeneration(id: generationID)
        }
        try withPinnedDirectory(
            root: root,
            relativePath: relativePath,
            createMissing: true,
            authorityCheck: authorityCheck
        ) { _, verifyDirectories in
            try withoutActuallyEscaping(verifyDirectories) { verifyDirectories in
                _ = try ProtectedFilePolicyV1.applyAndVerify(
                    .stagingDirectory,
                    relativePath: relativePath,
                    within: root,
                    authorityCheck: verifyDirectories
                )
            }
        }
    }

    func protectGenerationTree(
        id: UUID,
        root: URL,
        staging: Bool
    ) throws {
        let expected = staging ? generationFactory.restoreStagingGenerationURL(id: id)
            : generationFactory.installedGenerationURL(id: id)
        guard root.standardizedFileURL == expected.standardizedFileURL else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        // Use the same descriptor inventory and closed path classification as
        // migration/open/prune. The records-based expected tree remains a
        // separate, stronger restore completeness proof.
        if staging {
            try generationAuthority.protectStagingGeneration(id: id)
        } else {
            try generationAuthority.protectInstalledGeneration(id: id)
        }
    }

    private func validatedPathComponents(
        _ relativePath: String
    ) throws -> [String] {
        guard !relativePath.hasPrefix("/"),
              !relativePath.hasPrefix("\\"),
              !relativePath.contains("\\") else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        if relativePath.isEmpty { return [] }
        let components = relativePath.split(
            separator: "/",
            omittingEmptySubsequences: false
        ).map(String.init)
        guard !components.isEmpty,
              components.allSatisfy({
                  !$0.isEmpty && $0 != "." && $0 != ".."
              }) else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        return components
    }

    private func withPinnedDirectory<T>(
        root: URL,
        relativePath: String,
        createMissing: Bool,
        authorityCheck: () throws -> Void,
        body: (Int32, () throws -> Void) throws -> T
    ) throws -> T {
        let components = try validatedPathComponents(relativePath)
        try authorityCheck()
        let rootDescriptor = Darwin.open(
            root.path,
            O_RDONLY | O_DIRECTORY | O_NOFOLLOW
        )
        guard rootDescriptor >= 0 else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        var descriptors = [rootDescriptor]
        defer {
            for descriptor in descriptors.reversed() {
                _ = Darwin.close(descriptor)
            }
        }

        var rootInformation = stat()
        guard Darwin.fstat(rootDescriptor, &rootInformation) == 0,
              (rootInformation.st_mode & S_IFMT) == S_IFDIR else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        var pins = [PinnedDirectory(
            descriptor: rootDescriptor,
            identity: PinnedIdentity(rootInformation),
            parent: nil,
            name: nil
        )]
        var current = rootDescriptor
        for component in components {
            var descriptor = Darwin.openat(
                current,
                component,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW
            )
            if descriptor < 0, errno == ENOENT, createMissing {
                guard Darwin.mkdirat(
                    current,
                    component,
                    mode_t(0o700)
                ) == 0 || errno == EEXIST,
                      Darwin.fsync(current) == 0 else {
                    throw attributedRestoreAuthorityFailureV1(line: #line)
                }
                descriptor = Darwin.openat(
                    current,
                    component,
                    O_RDONLY | O_DIRECTORY | O_NOFOLLOW
                )
            }
            guard descriptor >= 0 else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            descriptors.append(descriptor)
            var information = stat()
            guard Darwin.fstat(descriptor, &information) == 0,
                  (information.st_mode & S_IFMT) == S_IFDIR else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            pins.append(PinnedDirectory(
                descriptor: descriptor,
                identity: PinnedIdentity(information),
                parent: current,
                name: component
            ))
            current = descriptor
        }

        return try withoutActuallyEscaping(authorityCheck) { authorityCheck in
            let pinned = pins
            func verifyDirectories() throws {
                try authorityCheck()
                for pin in pinned {
                    var information = stat()
                    guard Darwin.fstat(pin.descriptor, &information) == 0,
                          PinnedIdentity(information) == pin.identity else {
                        throw attributedRestoreAuthorityFailureV1(line: #line)
                    }
                    if let parent = pin.parent, let name = pin.name {
                        var pathInformation = stat()
                        guard Darwin.fstatat(
                            parent,
                            name,
                            &pathInformation,
                            AT_SYMLINK_NOFOLLOW
                        ) == 0,
                              PinnedIdentity(pathInformation) == pin.identity else {
                            throw attributedRestoreAuthorityFailureV1(line: #line)
                        }
                    }
                }
            }
            try verifyDirectories()
            let result = try body(current, verifyDirectories)
            try verifyDirectories()
            return result
        }
    }

    private func withPinnedExistingItem<T>(
        root: URL,
        relativePath: String,
        expectedDirectory: Bool,
        authorityCheck: () throws -> Void,
        body: (Int32, Int32, () throws -> Void) throws -> T
    ) throws -> T {
        let components = try validatedPathComponents(relativePath)
        guard let name = components.last else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        let parentRelative = components.dropLast().joined(separator: "/")
        return try withPinnedDirectory(
            root: root,
            relativePath: parentRelative,
            createMissing: false,
            authorityCheck: authorityCheck
        ) { parentDescriptor, verifyDirectories in
            let flags: Int32 = expectedDirectory
                ? (O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
                : (O_RDONLY | O_NONBLOCK | O_NOFOLLOW)
            let descriptor = Darwin.openat(parentDescriptor, name, flags)
            guard descriptor >= 0 else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            defer { _ = Darwin.close(descriptor) }
            var information = stat()
            guard Darwin.fstat(descriptor, &information) == 0 else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            let identity = PinnedIdentity(information)
            let expectedType = expectedDirectory
                ? UInt32(S_IFDIR)
                : UInt32(S_IFREG)
            guard identity.type == expectedType,
                  expectedDirectory || identity.linkCount == 1 else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            return try withoutActuallyEscaping(verifyDirectories) { verifyDirectories in
                func verifyItem() throws {
                    try verifyDirectories()
                    guard try itemIdentity(
                        parent: parentDescriptor,
                        name: name
                    ) == identity else {
                        throw attributedRestoreAuthorityFailureV1(line: #line)
                    }
                    var descriptorInformation = stat()
                    guard Darwin.fstat(descriptor, &descriptorInformation) == 0,
                          PinnedIdentity(descriptorInformation) == identity else {
                        throw attributedRestoreAuthorityFailureV1(line: #line)
                    }
                }
                try verifyItem()
                let result = try body(parentDescriptor, descriptor, verifyItem)
                try verifyItem()
                return result
            }
        }
    }

    private func itemExists(
        parent: Int32,
        name: String
    ) throws -> Bool {
        var information = stat()
        if Darwin.fstatat(
            parent,
            name,
            &information,
            AT_SYMLINK_NOFOLLOW
        ) == 0 {
            return true
        }
        if errno == ENOENT { return false }
        throw attributedRestoreAuthorityFailureV1(line: #line)
    }

    nonisolated private func itemIdentity(
        parent: Int32,
        name: String
    ) throws -> PinnedIdentity {
        var information = stat()
        guard Darwin.fstatat(
            parent,
            name,
            &information,
            AT_SYMLINK_NOFOLLOW
        ) == 0 else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        guard (information.st_mode & S_IFMT) != S_IFLNK else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        return PinnedIdentity(information)
    }

    private func readRegularFile(
        parent: Int32,
        name: String,
        expected: PinnedIdentity
    ) throws -> Data {
        let descriptor = Darwin.openat(
            parent,
            name,
            O_RDONLY | O_NOFOLLOW
        )
        guard descriptor >= 0 else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        defer { _ = Darwin.close(descriptor) }
        var before = stat()
        guard Darwin.fstat(descriptor, &before) == 0,
              PinnedIdentity(before) == expected,
              expected.type == UInt32(S_IFREG),
              expected.linkCount == 1 else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        var data = Data()
        var buffer = [UInt8](repeating: 0, count: 16 * 1024)
        while true {
            let count = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if count > 0 {
                data.append(contentsOf: buffer.prefix(count))
            } else if count == 0 {
                break
            } else if errno != EINTR {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
        }
        var after = stat()
        guard Darwin.fstat(descriptor, &after) == 0,
              PinnedIdentity(after) == expected,
              data.count == Int(after.st_size),
              try itemIdentity(parent: parent, name: name) == expected else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        return data
    }

    func installedFileKind(_ relativePath: String) throws -> OwnedFileKindV1 {
        do {
            return try GenerationOwnedPathV1.classify(relativePath, nodeType: .regularFile).kind
        } catch {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
    }

    func relativePath(of url: URL, within root: URL) throws -> String {
        let rootPath = root.standardizedFileURL.path
        let valuePath = url.standardizedFileURL.path
        guard valuePath.hasPrefix(rootPath + "/") else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        let value = String(valuePath.dropFirst(rootPath.count + 1))
        guard !value.isEmpty,
              !value.contains("\\"),
              !value.split(separator: "/", omittingEmptySubsequences: false)
                .contains(where: { $0.isEmpty || $0 == "." || $0 == ".." }) else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        return value
    }

