    func expectedGenerationTree(
        records: V4BackupRecordsV1,
        photoPlans: [CheckRunnerPhotoBackupRestorePlanV1] = []
    ) throws -> (
        directories: Set<String>,
        files: Set<String>,
        optionalDirectories: Set<String>,
        optionalFiles: Set<String>
    ) {
        var expectedFiles: Set<String> = ["model.sqlite"]
        var expectedDirectories = Set<String>()
        var optionalDirectories = Set<String>()
        var optionalFiles = Set<String>()
        for path in try photoGenerationMembers(photoPlans).keys {
            expectedFiles.insert(path)
            var components = path.split(separator: "/").map(String.init)
            components.removeLast()
            while !components.isEmpty {
                expectedDirectories.insert(components.joined(separator: "/"))
                components.removeLast()
            }
        }
        if !records.evidenceFiles.isEmpty {
            expectedDirectories.insert("evidence")
        }
        for evidence in records.evidenceFiles {
            expectedDirectories.insert("evidence/\(canonical(evidence.id))")
            expectedFiles.insert(evidence.relativePath)
            expectedFiles.insert(evidence.thumbnailRelativePath)
        }
        let temporal = try decodedTemporalEvidenceRows(records)
        for clip in temporal.clips {
            let workspace = clip.workspaceID.rawValue.uuidString.lowercased()
            let contentID = clip.original.contentID
            expectedDirectories.insert("content")
            expectedDirectories.insert("content/\(workspace)")
            expectedDirectories.insert("content/\(workspace)/\(contentID)")
            expectedFiles.insert("content/\(workspace)/\(contentID)/original.bin")
        }
        for record in records.acceptedLabelGenerationSnapshots {
            let snapshot = try record.value()
            guard snapshot.disposition == .activeSourceWorkspace else { continue }
            let binding = snapshot.outputReceipt.publicationBinding
            try binding.validate(manifest: snapshot.manifest)
            let workspace = snapshot.workspaceID.rawValue.uuidString.lowercased()
            guard binding.workspaceID == snapshot.workspaceID else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
            optionalDirectories.insert("content")
            optionalDirectories.insert("content/\(workspace)")
            optionalDirectories.insert("content/\(workspace)/.asset-label-publications")
            optionalDirectories.insert(
                "content/\(workspace)/.asset-label-publications/\(binding.jobID.rawValue.uuidString.lowercased())"
            )
            optionalFiles.insert(
                "content/\(workspace)/.asset-label-publications/\(binding.jobID.rawValue.uuidString.lowercased())/publication.json"
            )
            for artifact in binding.publishedArtifacts {
                let directory = "content/\(workspace)/\(artifact.reference.contentID)"
                optionalDirectories.insert(directory)
                optionalFiles.insert("\(directory)/original.bin")
            }
        }
        if records.recordsSchemaVersion >= C05EvidenceMetadataBackupEnrollmentV1.recordsSchemaVersion {
            var contentKeys = Set<String>()
            for event in records.evidenceAssociationEvents {
                for contentID in [event.contentID, event.previousContentID].compactMap({ $0 }) {
                    contentKeys.insert("\(event.workspaceID)|\(contentID)")
                }
            }
            for key in contentKeys {
                let components = key.split(separator: "|", maxSplits: 1).map(String.init)
                guard components.count == 2 else { throw attributedRestoreAuthorityFailureV1(line: #line) }
                let directory = "content/\(components[0])/\(components[1])"
                optionalDirectories.formUnion(["content", "content/\(components[0])", directory])
                optionalFiles.insert("\(directory)/original.bin")
                optionalFiles.insert("\(directory)/derivative-publication.json")
            }
        }
        if !records.reports.isEmpty {
            expectedDirectories.insert("snapshots")
        }
        if records.reports.contains(where: {
            $0.pdfState == ReportPDFState.ready.rawValue
        }) {
            expectedDirectories.insert("pdfs")
        }
        for report in records.reports {
            expectedFiles.insert(report.snapshotRelativePath)
            if let path = report.pdfRelativePath {
                expectedFiles.insert(path)
            }
        }
        optionalFiles.formUnion([
            "model.sqlite-shm",
            "model.sqlite-wal",
        ])
        return (
            expectedDirectories,
            expectedFiles,
            optionalDirectories,
            optionalFiles
        )
    }

    var allowedEmptyStagingDirectories: Set<String> {
        [
            ".staging",
            ".staging/evidence",
            ".staging/pdfs",
            ".staging/snapshots",
        ]
    }

    func validInstalledGeneration(
        id: UUID,
        identity: WorkspaceReplicaIdentityV1? = nil,
        requireExportReconciliation: Bool = true,
        incumbentCloneRetirement: ConfigurationCloneRetirementBindingV1? = nil
    ) throws -> StoreGenerationSession? {
        let session: StoreGenerationSession
        do {
            if let identity {
                session = try generationFactory.openInstalledGeneration(
                    id: id,
                    identity: identity,
                    authority: generationAuthority
                )
            } else {
                session = try generationFactory.openInstalledGeneration(
                    id: id,
                    authority: generationAuthority
                )
            }
        } catch let failure as ProtectedFilePolicyError
            where failure == .protectedDataUnavailable {
            throw failure
        } catch {
            return nil
        }
        do {
            try protectGenerationTree(
                id: id,
                root: session.generationRootURL,
                staging: false
            )
        } catch let failure as ProtectedFilePolicyError
            where failure == .protectedDataUnavailable {
            throw failure
        } catch {
            return nil
        }
        do {
            let frozenRecords = try records(in: session.modelContext)
            let photoPlans = try incumbentCloneRetirement.map { [try $0.core.resolveCurrent(in: frozenRecords)] } ?? []
            if requireExportReconciliation {
                try validateLiveSession(session, expected: frozenRecords, photoPlans: photoPlans)
            } else {
                try validateUnpublishedTargetSession(
                    session,
                    expected: frozenRecords,
                    staging: false,
                    photoPlans: photoPlans
                )
            }
        } catch let failure as ProtectedFilePolicyError
            where failure == .protectedDataUnavailable {
            throw failure
        } catch {
            return nil
        }
        return session
    }

    func validStagingGenerationRecords(
        id: UUID,
        identity: WorkspaceReplicaIdentityV1? = nil
    ) throws -> V4BackupRecordsV1? {
        do {
            let session: StoreGenerationSession
            if let identity {
                session = try generationFactory.openRestoreStagingGeneration(
                    id: id,
                    identity: identity,
                    authority: generationAuthority
                )
            } else {
                session = try generationFactory.openRestoreStagingGeneration(
                    id: id,
                    authority: generationAuthority
                )
            }
            try protectGenerationTree(
                id: id,
                root: session.generationRootURL,
                staging: true
            )
            guard !session.modelContext.hasChanges else { return nil }
            let frozenRecords = try records(in: session.modelContext)
            try validateFrozenFiles(
                root: session.generationRootURL,
                records: frozenRecords,
                authorityCheck: {
                    try generationAuthority.requireStagingGeneration(id: id)
                }
            )
            try validateGenerationTree(
                generationAuthority.stagingTree(id: id),
                records: frozenRecords,
                generationRootURL: session.generationRootURL
            )
            try requireAbsentAssetLabelPublications(
                generationAuthority.stagingTree(id: id),
                records: frozenRecords
            )
            return frozenRecords
        } catch let failure as ProtectedFilePolicyError
            where failure == .protectedDataUnavailable {
            throw failure
        } catch {
            return nil
        }
    }

    func validMonotonicUnion(
        from current: V4BackupRecordsV1,
        to replacement: V4BackupRecordsV1,
        replacementAt: Date
    ) -> Bool {
        guard let plan = try? ReplacementRestoreRule.makeDeletionWinningPlan(
            DeletionWinningRestoreInputV2(
                currentRecords: current,
                incomingRecords: replacement,
                mode: .replaceExisting,
                replacementAt: replacementAt
            )
        ) else {
            return false
        }
        var recoveredRecords = plan.recordsAfter
        // The replacement snapshot is the authenticated recovery authority;
        // the generic merge helper cannot carry the later V52 archive family.
        recoveredRecords.lightingDayInventoryWorkflows =
            replacement.lightingDayInventoryWorkflows
        recoveredRecords.lightingNightWorkflows = replacement.lightingNightWorkflows
        return recoveredRecords == replacement
    }

    func validateRows(
        _ context: ModelContext,
        expected: V4BackupRecordsV1
    ) throws {
        let actual = try records(in: context)
        if actual == expected { return }
        guard expected.recordsSchemaVersion < 9,
              (actual.recordsSchemaVersion == 9 || actual.recordsSchemaVersion == 10
                || actual.recordsSchemaVersion == 11
                || actual.recordsSchemaVersion == 12
                || actual.recordsSchemaVersion == 13
                || actual.recordsSchemaVersion == 14
                || actual.recordsSchemaVersion == 15
                || actual.recordsSchemaVersion == 16
                || actual.recordsSchemaVersion == 17
                || actual.recordsSchemaVersion == 18
                || actual.recordsSchemaVersion == 19
                || actual.recordsSchemaVersion == 20
                || actual.recordsSchemaVersion == 21
                || actual.recordsSchemaVersion == 22
                || actual.recordsSchemaVersion == 23
                || actual.recordsSchemaVersion == 24) else {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
        if expected.recordsSchemaVersion == 5 || expected.recordsSchemaVersion == 6 {
            guard recordsByReplacingV7Fields(
                actual, schemaVersion: expected.recordsSchemaVersion
            ) == expected else {
                throw attributedRestoreAuthorityFailureV1(line: #line)
            }
        } else if try !validLegacyLocationMigration(actual, expected: expected) {
            throw attributedRestoreAuthorityFailureV1(line: #line)
        }
    }

