    ) -> V4BackupRecordsV1 {
        V4BackupRecordsV1(
            guidedSurveys:schemaVersion >= 24 ? records.guidedSurveys:[],
            assetLocators: schemaVersion >= 25 ? records.assetLocators : [],
            schedules: schemaVersion >= 26 ? records.schedules : [],
